PathwayData.put("data/reading_writing/units/L01U5.json",{"strand":"reading_writing","level":1,"cefr":"A1a","unit":5,"theme":"Food and Healthy Eating","essential_question":"Which foods help us grow strong?","schema_version":"1.0","core_words":["bread","rice","milk","water","apple","banana","dates","egg","chicken","vegetables","dinner","hungry","healthy","wash"],"recycled_words":["happy","like","favorite","kitchen","table","breakfast","lunch","plate","ready","first","next","last","different"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L01-U5-LS1","title":"Word Power: Food and Healthy Eating","lesson_type":"vocabulary","objectives":["read and say 14 food words and 2 Tier 2 words (group, choose)","sort food words into groups: fruits, drinks, main foods and meals","talk and write about healthy food they like"],"objectives_ar":["قراءة ونطق 14 كلمة عن الطعام وكلمتين أكاديميتين (group, choose).","تصنيف كلمات الطعام في مجموعات: فواكه، مشروبات، أطعمة رئيسية، وجبات.","التحدث والكتابة عن الطعام الصحي الذي يحبونه."],"success_criteria":["I can read and say the food words.","I can put food words in groups.","I can say what healthy food I like."],"success_criteria_ar":["أستطيع قراءة كلمات الطعام ونطقها.","أستطيع وضع كلمات الطعام في مجموعات.","أستطيع قول ما أحبه من الطعام الصحي."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"bread","pos":"noun","ipa":"/brɛd/","definition":"a food made from flour and baked","arabic":"خبز","example":"I eat bread with cheese.","image_id":"IMG-RW-L01-U5-LS1-V01","audio_id":"AUD-RW-L01-U5-LS1-V01","tier":"core"},{"word":"rice","pos":"noun","ipa":"/raɪs/","definition":"small white or brown grains we cook","arabic":"أرز","example":"We eat rice and chicken.","image_id":"IMG-RW-L01-U5-LS1-V02","audio_id":"AUD-RW-L01-U5-LS1-V02","tier":"core"},{"word":"milk","pos":"noun","ipa":"/mɪlk/","definition":"a white drink from cows, goats or camels","arabic":"حليب","example":"Milk is good for your bones.","image_id":"IMG-RW-L01-U5-LS1-V03","audio_id":"AUD-RW-L01-U5-LS1-V03","tier":"core"},{"word":"water","pos":"noun","ipa":"/ˈwɔtər/","definition":"the clear drink we need every day","arabic":"ماء","example":"Drink water every day.","image_id":"IMG-RW-L01-U5-LS1-V04","audio_id":"AUD-RW-L01-U5-LS1-V04","tier":"core"},{"word":"apple","pos":"noun","ipa":"/ˈæpəl/","definition":"a round red or green fruit","arabic":"تفاحة","example":"The apple is red.","image_id":"IMG-RW-L01-U5-LS1-V05","audio_id":"AUD-RW-L01-U5-LS1-V05","tier":"core"},{"word":"banana","pos":"noun","ipa":"/bəˈnænə/","definition":"a long yellow fruit","arabic":"موزة","example":"Monkeys like bananas.","image_id":"IMG-RW-L01-U5-LS1-V06","audio_id":"AUD-RW-L01-U5-LS1-V06","tier":"core"},{"word":"dates","pos":"noun","ipa":"/deɪts/","definition":"small brown sweet fruits from palm trees","arabic":"تمر","example":"We eat dates in Ramadan.","image_id":"IMG-RW-L01-U5-LS1-V07","audio_id":"AUD-RW-L01-U5-LS1-V07","tier":"core"},{"word":"egg","pos":"noun","ipa":"/ɛɡ/","definition":"food from a chicken with a shell","arabic":"بيضة","example":"I have an egg for breakfast.","image_id":"IMG-RW-L01-U5-LS1-V08","audio_id":"AUD-RW-L01-U5-LS1-V08","tier":"core"},{"word":"chicken","pos":"noun","ipa":"/ˈtʃɪkən/","definition":"a farm bird; also its meat as food","arabic":"دجاج","example":"Mother cooks chicken.","image_id":"IMG-RW-L01-U5-LS1-V09","audio_id":"AUD-RW-L01-U5-LS1-V09","tier":"core"},{"word":"vegetables","pos":"noun","ipa":"/ˈvɛdʒtəbəlz/","definition":"plants we eat, like carrots and cucumbers","arabic":"خضراوات","example":"Vegetables help you grow.","image_id":"IMG-RW-L01-U5-LS1-V10","audio_id":"AUD-RW-L01-U5-LS1-V10","tier":"core"},{"word":"dinner","pos":"noun","ipa":"/ˈdɪnər/","definition":"the meal in the evening","arabic":"العشاء","example":"We have dinner at eight.","image_id":"IMG-RW-L01-U5-LS1-V11","audio_id":"AUD-RW-L01-U5-LS1-V11","tier":"core"},{"word":"hungry","pos":"adjective","ipa":"/ˈhʌŋɡri/","definition":"wanting to eat food","arabic":"جائع","example":"I am hungry after school.","image_id":"IMG-RW-L01-U5-LS1-V12","audio_id":"AUD-RW-L01-U5-LS1-V12","tier":"core"},{"word":"healthy","pos":"adjective","ipa":"/ˈhɛlθi/","definition":"good for your body","arabic":"صحي","example":"Fruit is healthy.","image_id":"IMG-RW-L01-U5-LS1-V13","audio_id":"AUD-RW-L01-U5-LS1-V13","tier":"core"},{"word":"wash","pos":"verb","ipa":"/wɑʃ/","definition":"to clean with water","arabic":"يغسل","example":"Wash the apple first.","image_id":"IMG-RW-L01-U5-LS1-V14","audio_id":"AUD-RW-L01-U5-LS1-V14","tier":"core"},{"word":"group","pos":"noun","ipa":"/ɡrup/","definition":"things that go together","arabic":"مجموعة","example":"Apples and bananas are in the fruit group.","image_id":"IMG-RW-L01-U5-LS1-V15","audio_id":"AUD-RW-L01-U5-LS1-V15","tier":"tier2"},{"word":"choose","pos":"verb","ipa":"/tʃuz/","definition":"to pick one from many","arabic":"يختار","example":"Choose a healthy snack.","image_id":"IMG-RW-L01-U5-LS1-V16","audio_id":"AUD-RW-L01-U5-LS1-V16","tier":"tier2"}],"explanation":{"text":"We can put words in **groups**. Words in a group go together.\n\n**Fruits**: apple, banana, dates. **Drinks**: milk, water. **Main foods**: bread, rice, egg, chicken, vegetables. **Meals**: breakfast, lunch, dinner.\n\nAsk: **Is it a fruit? A drink? A main food? A meal?** Then put it in its group. Groups help you remember words.","examples":["**apple** → fruits","**banana** → fruits","**dates** → fruits","**milk** → drinks","**water** → drinks","**rice** → main foods","**chicken** → main foods","**dinner** → meals","**breakfast** and **lunch** → meals (from Units 2 and 3)"],"common_errors":["✗ I eat a rice. → ✓ I eat rice. (No **a** before rice, milk, water, bread.)","✗ I drink a milk. → ✓ I drink milk. (No **a** before milk.)","✗ an banana → ✓ a banana (**a** before b; **an** before vowel sounds (an apple, an egg).)","✗ two breads → ✓ two pieces of bread (We do not say breads in this way.)","✗ I am hungry, I want to eat. → ✓ I am hungry. I want to eat. (Two sentences need a period between them.)","✗ The vegetables is healthy. → ✓ Vegetables are healthy. (Many → **are**.)","✗ I eat dinner in the night. → ✓ I eat dinner in the evening. (Use **in the evening** / **at night**.)"],"arabic":"نستطيع وضع الكلمات في مجموعات؛ الكلمات في المجموعة الواحدة تتناسب معًا.\n\nالفواكه: apple, banana, dates. المشروبات: milk, water. الأطعمة الرئيسية: bread, rice, egg, chicken, vegetables. الوجبات: breakfast, lunch, dinner.\n\nاسأل: هل هي فاكهة؟ مشروب؟ طعام رئيسي؟ وجبة؟ ثم ضعها في مجموعتها؛ المجموعات تساعدك على تذكّر الكلمات.\n\nانتبه: لا نضع a قبل rice وmilk وwater وbread."},"video":{"script":[{"time":"00:00–00:15","narration":"Sami is hungry! Let's go to the kitchen.","on_screen":"Food and Healthy Eating","visual":"Sami's tummy rumbles; he opens the kitchen door."},{"time":"00:15–00:45","narration":"Fruits! An apple, a banana, dates. Say: fruits!","on_screen":"Fruits 🍎🍌","visual":"Fruits roll into a basket labelled with a fruit icon."},{"time":"00:45–01:05","narration":"Drinks! Milk and water. Say: drinks!","on_screen":"Drinks 🥛💧","visual":"Glasses fill and slide onto a tray."},{"time":"01:05–01:35","narration":"Main foods! Bread, rice, an egg, chicken and vegetables.","on_screen":"Main foods 🍚🍗🥕","visual":"Plates appear on the table one by one."},{"time":"01:35–02:00","narration":"Meals! Breakfast in the morning, lunch at noon, dinner in the evening.","on_screen":"Breakfast · Lunch · Dinner","visual":"A sun moves across the sky over three tables."},{"time":"02:00–02:30","narration":"Choose healthy food. Wash it first. Now, eat!","on_screen":"Choose healthy food ✔","visual":"Sami washes an apple and takes a happy bite; Saqr gives a thumbs-up."}],"captions_ar":["سامي جائع! هيا إلى المطبخ.","الفواكه: تفاحة، موزة، تمر. قولوا: فواكه!","المشروبات: حليب وماء. قولوا: مشروبات!","الأطعمة الرئيسية: خبز، أرز، بيضة، دجاج، خضراوات.","الوجبات: الإفطار صباحًا، والغداء ظهرًا، والعشاء مساءً.","اختر الطعام الصحي واغسله أولًا، ثم كُل!"],"voice":"Narrator: American English, cheerful female teacher, speed 0.8. Sami: hungry, funny boy voice. Kitchen sound effects softly."},"texts":[],"activities":[{"id":"RW-L01-U5-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Which group does the word belong to?","instructions_ar":"إلى أي مجموعة تنتمي الكلمة؟","items":[{"q":"*banana* belongs to which group?","answer":"fruits","explanation":"A banana is a fruit.","explanation_ar":"الموز فاكهة.","options":["drinks","meals","fruits","main foods"],"dok":1,"skill":"word groups","stage":"controlled"},{"q":"*water* belongs to which group?","answer":"drinks","explanation":"We drink water.","explanation_ar":"الماء مشروب.","options":["drinks","fruits","meals","main foods"],"dok":1,"skill":"word groups","stage":"controlled"},{"q":"*rice* belongs to which group?","answer":"main foods","explanation":"Rice is a main food.","explanation_ar":"الأرز طعام رئيسي.","options":["drinks","main foods","fruits","meals"],"dok":1,"skill":"word groups","stage":"controlled"},{"q":"*dinner* belongs to which group?","answer":"meals","explanation":"Dinner is a meal.","explanation_ar":"العشاء وجبة.","options":["fruits","drinks","main foods","meals"],"dok":1,"skill":"word groups","stage":"controlled"},{"q":"Which word does NOT belong in the fruit group?","answer":"milk","explanation":"Milk is a drink.","explanation_ar":"الحليب مشروب.","options":["apple","dates","milk","banana"],"dok":2,"skill":"odd one out","stage":"controlled"},{"q":"Which word does NOT belong in the meal group?","answer":"egg","explanation":"An egg is a food, not a meal.","explanation_ar":"البيضة طعام وليست وجبة.","options":["breakfast","lunch","dinner","egg"],"dok":2,"skill":"odd one out","stage":"controlled"}]},{"id":"RW-L01-U5-LS1-A2","type":"gap_fill","stage":"guided","instructions":"Guided practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"I am ________. Can I have a sandwich?","answer":"hungry","explanation":"Hungry = want to eat.","explanation_ar":"جائع.","stage":"guided"},{"q":"Please ________ your hands before you eat.","answer":"wash","explanation":"We wash our hands.","explanation_ar":"اغسل يديك.","stage":"guided"},{"q":"Fruit and vegetables are ________ food.","answer":"healthy","explanation":"Healthy = good for your body.","explanation_ar":"صحي.","stage":"guided"},{"q":"We eat ________ in the evening.","answer":"dinner","explanation":"Evening meal = dinner.","explanation_ar":"العشاء.","stage":"guided"},{"q":"________ an apple or a banana for your snack.","answer":"Choose","explanation":"Choose = pick one.","explanation_ar":"اختر.","stage":"guided"},{"q":"Rice and bread are in the same ________.","answer":"group","explanation":"They go together.","explanation_ar":"المجموعة نفسها.","stage":"guided"}]},{"id":"RW-L01-U5-LS1-A3","type":"open","stage":"freer","instructions":"Freer practice: Sort the words into groups. Write them.","instructions_ar":"صنّف الكلمات واكتبها.","items":[{"q":"Fruits: apple, milk, dates, rice → write the fruits.","answer":"apple, dates","explanation":"Apple and dates are fruits.","explanation_ar":"التفاح والتمر فواكه.","dok":1,"skill":"word groups","stage":"freer"},{"q":"Drinks: water, egg, milk, bread → write the drinks.","answer":"water, milk","explanation":"Water and milk are drinks.","explanation_ar":"الماء والحليب مشروبات.","dok":1,"skill":"word groups","stage":"freer"},{"q":"Main foods: chicken, banana, vegetables, water → write the main foods.","answer":"chicken, vegetables","explanation":"Chicken and vegetables are main foods.","explanation_ar":"الدجاج والخضراوات أطعمة رئيسية.","dok":1,"skill":"word groups","stage":"freer"},{"q":"Add one more word to the fruit group.","answer":"orange","explanation":"Any fruit.","explanation_ar":"أي فاكهة.","dok":2,"skill":"word groups","stage":"freer"}]},{"id":"RW-L01-U5-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about YOUR food.","instructions_ar":"اكتب عن طعامك.","items":[{"q":"What is your favorite fruit?","answer":"My favorite fruit is dates.","explanation":"My favorite fruit is ___.","explanation_ar":"فاكهتي المفضلة.","dok":1,"skill":"personal writing","stage":"production"},{"q":"What do you drink at breakfast?","answer":"I drink milk at breakfast.","explanation":"I drink ___.","explanation_ar":"أشرب ___.","dok":1,"skill":"personal writing","stage":"production"},{"q":"What do you eat for dinner?","answer":"I eat bread and eggs for dinner.","explanation":"I eat ___ for dinner.","explanation_ar":"آكل ___ على العشاء.","dok":1,"skill":"personal writing","stage":"production"},{"q":"Write one healthy food and why you like it.","answer":"Bananas are healthy. They are sweet.","explanation":"Food + reason.","explanation_ar":"طعام + سبب.","dok":2,"skill":"personal writing","stage":"production"}]}],"game":{"name":"Healthy Shopping Basket","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Supermarket sort: food items roll along a conveyor belt; the child drags each into one of four baskets. Correct = a 'ding' and the item fills the basket; wrong = the item rolls back. 60 seconds.","Teams line up behind a pile of food cards.","One player at a time takes a card, says the word and its group (\"Banana – fruit!\") and puts it in the right basket.","Correct = 1 point; the next player goes.","After 2 minutes, count the correct cards in each basket.","The team with the most correct cards wins."],"data":[]},"exit_quiz":[{"q":"Which word is a drink?","answer":"milk","explanation":"We drink milk.","explanation_ar":"الحليب مشروب.","options":["apple","rice","milk","egg"],"dok":1,"skill":"word groups"},{"q":"Which word is a fruit?","answer":"banana","explanation":"A banana is a fruit.","explanation_ar":"الموز فاكهة.","options":["water","dinner","chicken","banana"],"dok":1,"skill":"word groups"},{"q":"Which word is a meal?","answer":"dinner","explanation":"Dinner is a meal.","explanation_ar":"العشاء وجبة.","options":["dinner","bread","dates","water"],"dok":1,"skill":"word groups"},{"q":"You want to eat. You are ___.","answer":"hungry","explanation":"Hungry = want to eat.","explanation_ar":"جائع.","options":["healthy","tiny","busy","hungry"],"dok":1,"skill":"vocabulary"},{"q":"Which food grows on palm trees?","answer":"dates","explanation":"Dates grow on palm trees.","explanation_ar":"التمر ينمو على النخيل.","options":["eggs","dates","rice","chicken"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about milk is correct?","answer":"I drink milk.","explanation":"No *a* before milk.","explanation_ar":"لا a قبل milk.","options":["I drink a milk.","I drink milk.","I drinks a milk.","I am drink milk."],"dok":2,"skill":"usage"},{"q":"Which word is the odd one out?","answer":"water","explanation":"Water is a drink; the others are main foods.","explanation_ar":"الماء مشروب.","options":["rice","bread","water","chicken"],"dok":2,"skill":"odd one out"},{"q":"Which choice is the most healthy snack?","answer":"an apple","explanation":"Fruit is healthy.","explanation_ar":"الفاكهة صحية.","options":["candy","an apple","chips","a soda"],"dok":2,"skill":"healthy choices"},{"q":"*Choose one fruit.* *Choose* means ___.","answer":"pick","explanation":"Choose = pick.","explanation_ar":"choose تعني اختر.","options":["pick","wash","cook","drink"],"dok":1,"skill":"vocabulary"},{"q":"Why do we wash fruit before we eat it?","answer":"to make it clean","explanation":"Washing cleans it.","explanation_ar":"الغسل ينظّفها.","options":["to make it clean","to make it sweet","to make it big","to make it cold"],"dok":3,"skill":"reasoning"}],"images":[{"id":"IMG-RW-L01-U5-LS1-V01","prompt":"Picture for the word 'bread': a round Arabic bread and a loaf"},{"id":"IMG-RW-L01-U5-LS1-V02","prompt":"Picture for the word 'rice': a plate of white rice"},{"id":"IMG-RW-L01-U5-LS1-V03","prompt":"Picture for the word 'milk': a glass of milk"},{"id":"IMG-RW-L01-U5-LS1-V04","prompt":"Picture for the word 'water': a glass of clear water"},{"id":"IMG-RW-L01-U5-LS1-V05","prompt":"Picture for the word 'apple': a shiny red apple"},{"id":"IMG-RW-L01-U5-LS1-V06","prompt":"Picture for the word 'banana': a yellow banana"},{"id":"IMG-RW-L01-U5-LS1-V07","prompt":"Picture for the word 'dates': a bowl of shiny brown dates"},{"id":"IMG-RW-L01-U5-LS1-V08","prompt":"Picture for the word 'egg': a boiled egg cut in half"},{"id":"IMG-RW-L01-U5-LS1-V09","prompt":"Picture for the word 'chicken': a plate of grilled chicken"},{"id":"IMG-RW-L01-U5-LS1-V10","prompt":"Picture for the word 'vegetables': carrots, cucumbers and tomatoes"},{"id":"IMG-RW-L01-U5-LS1-V11","prompt":"Picture for the word 'dinner': a family table at night with a lamp"},{"id":"IMG-RW-L01-U5-LS1-V12","prompt":"Picture for the word 'hungry': a boy holding his tummy looking at food"},{"id":"IMG-RW-L01-U5-LS1-V13","prompt":"Picture for the word 'healthy': a bowl of fruit with a green heart"},{"id":"IMG-RW-L01-U5-LS1-V14","prompt":"Picture for the word 'wash': hands washing an apple under a tap"},{"id":"IMG-RW-L01-U5-LS1-V15","prompt":"Picture for the word 'group': a circle around apples, bananas and dates"},{"id":"IMG-RW-L01-U5-LS1-V16","prompt":"Picture for the word 'choose': a child pointing at an apple instead of candy"},{"id":"IMG-RW-L01-U5-LS1-01","prompt":"Sami and Lama in a kitchen full of healthy food."},{"id":"IMG-RW-L01-U5-LS1-02","prompt":"Four baskets for food groups."},{"id":"IMG-RW-L01-U5-LS1-03","prompt":"Hands wash an apple under a tap."}],"audio":[{"id":"AUD-RW-L01-U5-LS1-V01","script":"bread. I eat bread with cheese."},{"id":"AUD-RW-L01-U5-LS1-V02","script":"rice. We eat rice and chicken."},{"id":"AUD-RW-L01-U5-LS1-V03","script":"milk. Milk is good for your bones."},{"id":"AUD-RW-L01-U5-LS1-V04","script":"water. Drink water every day."},{"id":"AUD-RW-L01-U5-LS1-V05","script":"apple. The apple is red."},{"id":"AUD-RW-L01-U5-LS1-V06","script":"banana. Monkeys like bananas."},{"id":"AUD-RW-L01-U5-LS1-V07","script":"dates. We eat dates in Ramadan."},{"id":"AUD-RW-L01-U5-LS1-V08","script":"egg. I have an egg for breakfast."},{"id":"AUD-RW-L01-U5-LS1-V09","script":"chicken. Mother cooks chicken."},{"id":"AUD-RW-L01-U5-LS1-V10","script":"vegetables. Vegetables help you grow."},{"id":"AUD-RW-L01-U5-LS1-V11","script":"dinner. We have dinner at eight."},{"id":"AUD-RW-L01-U5-LS1-V12","script":"hungry. I am hungry after school."},{"id":"AUD-RW-L01-U5-LS1-V13","script":"healthy. Fruit is healthy."},{"id":"AUD-RW-L01-U5-LS1-V14","script":"wash. Wash the apple first."},{"id":"AUD-RW-L01-U5-LS1-V15","script":"group. Apples and bananas are in the fruit group."},{"id":"AUD-RW-L01-U5-LS1-V16","script":"choose. Choose a healthy snack."},{"id":"AUD-RW-L01-U5-LS1-VID","script":"Sami is hungry! Let's go to the kitchen. Fruits! An apple, a banana, dates. Say: fruits! Drinks! Milk and water. Say: drinks! Main foods! Bread, rice, an egg, chicken and vegetables. Meals! Breakfast in the morning, lunch at noon, dinner in the evening. Choose healthy food. Wash it first. Now, eat!"}]},{"id":"RW-L01-U5-LS2","title":"What Is for Lunch?","lesson_type":"close_reading","objectives":["read a short play with expression and name its parts: characters, lines and stage directions","answer who, what and why questions about the play with evidence","explain how a character changes (Lama and vegetables)"],"objectives_ar":["قراءة مسرحية قصيرة بتعبير وتسمية أجزائها: الشخصيات والحوار والإرشادات المسرحية.","الإجابة عن أسئلة من وماذا ولماذا حول المسرحية مع الدليل.","شرح كيف تتغير الشخصية (لمى والخضراوات)."],"success_criteria":["I can read a character's lines with feeling.","I can find answers in the play.","I can say how Lama changes."],"success_criteria_ar":["أستطيع قراءة حوار الشخصية بإحساس.","أستطيع إيجاد الإجابات في المسرحية.","أستطيع قول كيف تغيرت لمى."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"play","pos":"noun","ipa":"/pleɪ/","definition":"a story that people act and speak","arabic":"مسرحية","example":"Our class acts a play.","image_id":"IMG-RW-L01-U5-LS2-V01","audio_id":"AUD-RW-L01-U5-LS2-V01","tier":"core"},{"word":"lines","pos":"noun","ipa":"/laɪnz/","definition":"the words a character says in a play","arabic":"حوار / أسطر الدور","example":"Learn your lines for the play.","image_id":"IMG-RW-L01-U5-LS2-V02","audio_id":"AUD-RW-L01-U5-LS2-V02","tier":"core"},{"word":"stage directions","pos":"noun","ipa":"/steɪdʒ dəˈrɛkʃənz/","definition":"words in ( ) that tell actors what to do","arabic":"إرشادات مسرحية","example":"The stage directions say: (smiling).","image_id":"IMG-RW-L01-U5-LS2-V03","audio_id":"AUD-RW-L01-U5-LS2-V03","tier":"core"},{"word":"strong","pos":"adjective","ipa":"/strɔŋ/","definition":"having a lot of power in your body","arabic":"قوي","example":"Milk helps you grow strong.","image_id":"IMG-RW-L01-U5-LS2-V04","audio_id":"AUD-RW-L01-U5-LS2-V04","tier":"core"},{"word":"grow","pos":"verb","ipa":"/ɡroʊ/","definition":"to get bigger","arabic":"يكبر / ينمو","example":"Plants grow in the sun.","image_id":"IMG-RW-L01-U5-LS2-V05","audio_id":"AUD-RW-L01-U5-LS2-V05","tier":"core"},{"word":"ready","pos":"adjective","ipa":"/ˈrɛdi/","definition":"prepared to start","arabic":"مستعد / جاهز","example":"I am ready to eat.","image_id":"IMG-RW-L01-U5-LS2-V06","audio_id":"AUD-RW-L01-U5-LS2-V06","tier":"core"},{"word":"smiling","pos":"verb","ipa":"/ˈsmaɪlɪŋ/","definition":"making a happy face","arabic":"مبتسم / يبتسم","example":"Lama is smiling.","image_id":"IMG-RW-L01-U5-LS2-V07","audio_id":"AUD-RW-L01-U5-LS2-V07","tier":"core"}],"explanation":{"text":"A **play** is a story that people **act**. It has **characters**, **lines** and **stage directions**.\n\nThe **character's name** comes first, then a colon (:), then the **lines** the character says: *Sami: I am hungry!*\n\n**Stage directions** are in brackets ( ). We do NOT say them aloud. They tell us where the characters are and what they do: *(smiling)*.\n\nRead each line with **feeling**: hungry, surprised, happy.","examples":["Characters: **Sami, Mother, Lama**.","Stage direction: **(The kitchen. Sami and Lama come in.)** → the place is the kitchen.","Line: **Sami:** I am hungry! → say it like a hungry boy.","Line: **Lama:** I do not like vegetables! → say it with a cross face.","Line: **Mother:** Vegetables are healthy. → say it kindly.","Stage direction: **(Sami and Lama wash their hands.)** → act it; do not say it.","Line: **Lama:** Now I am ready. Yum! → happy voice.","Stage direction: **(smiling)** → Lama smiles as she speaks.","Change: At first Lama does not like vegetables. At the end she says, \"They are good!\""],"common_errors":["✗ Reading the stage directions aloud as lines. → ✓ Act the stage directions; say only the lines. (Brackets ( ) mean 'do it', not 'say it'.)","✗ Reading the character's name as part of the line. → ✓ Sami: I am hungry! → say only \"I am hungry!\" (The name shows who speaks.)","✗ I not like vegetables. → ✓ I do not like vegetables. (Use **do not** before like.)","✗ Vegetables is healthy. → ✓ Vegetables are healthy. (Many → **are**.)","✗ They help you to grow strongly. → ✓ They help you grow strong. (Say **grow strong**.)","✗ Lama say they are good. → ✓ Lama says they are good. (One person → **says**.)"],"arabic":"المسرحية قصة يمثّلها أشخاص، ولها شخصيات وحوار وإرشادات مسرحية.\n\nيأتي اسم الشخصية أولًا ثم نقطتان (:) ثم الكلام الذي تقوله: Sami: I am hungry!\n\nالإرشادات المسرحية بين قوسين ( ) ولا نقرؤها بصوت عالٍ؛ إنها تخبرنا بالمكان وبما تفعله الشخصيات مثل (smiling).\n\nاقرأ كل سطر بإحساس: جائع، متفاجئ، سعيد. وانتبه: نقول I do not like ولا نقول I not like."},"video":{"script":[{"time":"00:00–00:20","narration":"A play is a story we act! Look: names, lines and stage directions.","on_screen":"Reading a play 🎭","visual":"A script page with colored highlights: names (blue), lines (black), brackets (coral)."},{"time":"00:20–01:30","narration":"Sami: I am hungry! What is for lunch? Mother: Rice, chicken and vegetables…","on_screen":"(the play, acted)","visual":"Cartoon actors perform the play in the kitchen; each line's speaker glows."},{"time":"01:30–01:55","narration":"The words in brackets are stage directions. We do them. We don't say them!","on_screen":"( ) = do it, don't say it","visual":"Lama and Sami wash their hands silently while '(Sami and Lama wash their hands.)' appears."},{"time":"01:55–02:25","narration":"Look at Lama. First: 'I do not like vegetables!' Last: 'They are good!' Lama changes!","on_screen":"Lama changes 😠 → 😊","visual":"Two pictures of Lama side by side: cross face, then smiling face."},{"time":"02:25–02:50","narration":"Now you act it! Read your lines with feeling.","on_screen":"Act it out!","visual":"Saqr holds up a small stage curtain; children take a bow."}],"captions_ar":["المسرحية قصة نمثّلها! انظروا: الأسماء والحوار والإرشادات المسرحية.","سامي: أنا جائع! ماذا يوجد على الغداء؟ الأم: أرز ودجاج وخضراوات…","الكلمات بين القوسين إرشادات مسرحية: نمثّلها ولا نقولها!","انظروا إلى لمى: في البداية لا تحب الخضراوات، وفي النهاية تقول: إنها لذيذة! لقد تغيّرت لمى.","والآن مثّلوها! اقرؤوا أدواركم بإحساس."],"voice":"Three voices: Mother (warm adult female), Sami (hungry, lively boy), Lama (small girl, cross then happy). Narrator: American English female teacher, speed 0.8."},"texts":[{"type":"reading","title":"What Is for Lunch?","body":"*Characters: Sami, Mother, Lama*\n\n*(The kitchen. Sami and Lama come in.)*\n\n**Sami:** I am hungry! What is for lunch?\n\n**Mother:** Rice, chicken and vegetables.\n\n**Lama:** I do not like vegetables!\n\n**Mother:** Vegetables are healthy. They help you grow strong.\n\n**Sami:** Can we have dates and milk too?\n\n**Mother:** Yes! But first, wash your hands.\n\n*(Sami and Lama wash their hands.)*\n\n**Lama:** Now I am ready. Yum! Rice and chicken!\n\n**Sami:** Look, Lama. You eat vegetables too!\n\n**Lama:** *(smiling)* They are good!","word_count":81,"audio_id":"AUD-RW-L01-U5-LS2-T1","id":"TXT-RW-L01-U5-LS2-1","genre":"drama","role":"main","difficulty":"BR–200L","glossary":[{"word":"Yum!","definition":"a word we say when food is very good","arabic":"لذيذ!"},{"word":"grow strong","definition":"become big and strong","arabic":"تكبر وتصبح قويًا"}]}],"activities":[{"id":"RW-L01-U5-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the play. Choose the answer.","instructions_ar":"اقرأ المسرحية واختر الإجابة.","items":[{"q":"Where are the characters?","answer":"in the kitchen","explanation":"Stage direction: (The kitchen.)","explanation_ar":"في المطبخ.","options":["at school","in the garden","on a farm","in the kitchen"],"dok":1,"skill":"setting","stage":"controlled"},{"q":"Who is hungry at the start?","answer":"Sami","explanation":"Sami: I am hungry!","explanation_ar":"سامي جائع.","options":["Mother","Lama","Omar","Sami"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What is for lunch?","answer":"rice, chicken and vegetables","explanation":"Mother: Rice, chicken and vegetables.","explanation_ar":"أرز ودجاج وخضراوات.","options":["bread and eggs","rice, chicken and vegetables","fish and rice","dates only"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who does not like vegetables?","answer":"Lama","explanation":"Lama: I do not like vegetables!","explanation_ar":"لمى.","options":["Sami","Mother","Lama","Grandpa"],"dok":1,"skill":"characters","stage":"controlled"},{"q":"What does Sami ask for too?","answer":"dates and milk","explanation":"Sami: Can we have dates and milk too?","explanation_ar":"التمر والحليب.","options":["dates and milk","water and bread","eggs and apples","a banana"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What must the children do first?","answer":"wash their hands","explanation":"Mother: But first, wash your hands.","explanation_ar":"غسل اليدين.","options":["wash their hands","eat dates","sit in the garden","drink milk"],"dok":1,"skill":"sequence","stage":"controlled"}]},{"id":"RW-L01-U5-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: True or false?","instructions_ar":"صح أم خطأ؟","items":[{"q":"There are three characters in the play.","answer":"true","explanation":"Sami, Mother and Lama.","explanation_ar":"ثلاث شخصيات.","options":["true","false"],"stage":"guided"},{"q":"We read the stage directions aloud.","answer":"false","explanation":"We act them; we don't say them.","explanation_ar":"لا نقرؤها بصوت عالٍ.","options":["true","false"],"stage":"guided"},{"q":"Mother says vegetables are healthy.","answer":"true","explanation":"Mother: Vegetables are healthy.","explanation_ar":"صحيح.","options":["true","false"],"stage":"guided"},{"q":"Lama eats vegetables at the end.","answer":"true","explanation":"Sami: You eat vegetables too!","explanation_ar":"صحيح.","options":["true","false"],"stage":"guided"},{"q":"Sami does not want dates.","answer":"false","explanation":"He asks for dates and milk.","explanation_ar":"يطلب التمر.","options":["true","false"],"stage":"guided"},{"q":"Lama is cross at the end of the play.","answer":"false","explanation":"She is smiling.","explanation_ar":"إنها مبتسمة.","options":["true","false"],"stage":"guided"}]},{"id":"RW-L01-U5-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence. Underline or choose.","instructions_ar":"ابحث عن الدليل: ضع خطًا أو اختر.","items":[{"q":"Underline the line that shows why vegetables are good.","answer":"Mother: Vegetables are healthy. They help you grow strong.","explanation":"Mother explains why.","explanation_ar":"الأم توضّح السبب.","evidence":"Mother: Vegetables are healthy. They help you grow strong.","text_id":"TXT-RW-L01-U5-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["*Characters: Sami, Mother, Lama*","*(The kitchen.","Sami and Lama come in.)*","**Sami:** I am hungry!","What is for lunch?","**Mother:** Rice, chicken and vegetables.","**Lama:** I do not like vegetables!","**Mother:** Vegetables are healthy.","They help you grow strong.","**Sami:** Can we have dates and milk too?","**Mother:** Yes!","But first, wash your hands.","*(Sami and Lama wash their hands.)*","**Lama:** Now I am ready.","Yum!","Rice and chicken!","**Sami:** Look, Lama.","You eat vegetables too!","**Lama:** *(smiling)* They are good!"]},{"q":"Underline the stage direction that shows Lama is happy.","answer":"(smiling)","explanation":"Smiling shows happiness.","explanation_ar":"الابتسامة تدل على السعادة.","evidence":"(smiling)","text_id":"TXT-RW-L01-U5-LS2-1","dok":2,"skill":"stage directions","stage":"freer","sentences":["*Characters: Sami, Mother, Lama*","*(The kitchen.","Sami and Lama come in.)*","**Sami:** I am hungry!","What is for lunch?","**Mother:** Rice, chicken and vegetables.","**Lama:** I do not like vegetables!","**Mother:** Vegetables are healthy.","They help you grow strong.","**Sami:** Can we have dates and milk too?","**Mother:** Yes!","But first, wash your hands.","*(Sami and Lama wash their hands.)*","**Lama:** Now I am ready.","Yum!","Rice and chicken!","**Sami:** Look, Lama.","You eat vegetables too!","**Lama:** *(smiling)* They are good!"]},{"q":"How does Lama change in the play?","answer":"At first she does not like vegetables; at the end she likes them.","explanation":"Compare her first and last lines.","explanation_ar":"قارن بين أول كلامها وآخره.","options":["At first she is happy; at the end she is sad.","At first she does not like vegetables; at the end she likes them.","She does not change.","She stops eating."],"dok":2,"skill":"character change","stage":"freer"},{"q":"Why does Mother tell them to wash their hands?","answer":"to be clean before eating","explanation":"We wash hands before we eat.","explanation_ar":"لنظافة اليدين قبل الأكل.","options":["to play a game","to go to school","to be clean before eating","to cook the rice"],"dok":2,"skill":"inference","stage":"freer"}]},{"id":"RW-L01-U5-LS2-A4","type":"open","stage":"production","instructions":"Writing: Write and act.","instructions_ar":"اكتب ومثّل.","items":[{"q":"Write a new line for Mother at the end of the play.","answer":"Mother: Well done, Lama! Now drink your milk.","explanation":"Name + colon + line.","explanation_ar":"الاسم + نقطتان + الكلام.","dok":2,"skill":"play writing","stage":"production"},{"q":"Write a stage direction for Sami at the end.","answer":"(Sami claps his hands.)","explanation":"Brackets + action.","explanation_ar":"قوسان + فعل.","dok":2,"skill":"stage directions","stage":"production"},{"q":"Do you like vegetables? Write a line like Lama.","answer":"I like carrots!","explanation":"A true sentence.","explanation_ar":"جملة صحيحة.","dok":1,"skill":"connect","stage":"production"},{"q":"Is Mother a good mother? Why?","answer":"Yes. She gives them healthy food and helps them.","explanation":"Yes/No + reason.","explanation_ar":"نعم/لا + سبب.","dok":3,"skill":"evaluate","stage":"production"}]},{"id":"RW-L01-U5-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"What Is for Lunch?\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “What Is for Lunch?”.","answer":"81 words","title":"What Is for Lunch?","body":"*Characters: Sami, Mother, Lama*\n\n*(The kitchen. Sami and Lama come in.)*\n\n**Sami:** I am hungry! What is for lunch?\n\n**Mother:** Rice, chicken and vegetables.\n\n**Lama:** I do not like vegetables!\n\n**Mother:** Vegetables are healthy. They help you grow strong.\n\n**Sami:** Can we have dates and milk too?\n\n**Mother:** Yes! But first, wash your hands.\n\n*(Sami and Lama wash their hands.)*\n\n**Lama:** Now I am ready. Yum! Rice and chicken!\n\n**Sami:** Look, Lama. You eat vegetables too!\n\n**Lama:** *(smiling)* They are good!","words":81,"limit":136}],"time_limit_sec":136}],"game":{"name":"Voice Dice Theater","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Read-aloud mirror: a line from the play appears with a feeling emoji; the child records the line with that feeling and plays it back. Stars for finishing 6 lines.","Each team has a die and a pile of line cards.","A player takes a line card and rolls the die.","The player reads the line with the feeling on the die.","The team guesses the feeling.","Correct guess = 1 point for the reader and 1 for the team."],"data":[]},"exit_quiz":[{"q":"A play is a story that people ___.","answer":"act","explanation":"Plays are acted.","explanation_ar":"المسرحية تُمثَّل.","options":["draw","act","swim","cook"],"dok":1,"skill":"genre"},{"q":"In a play, words in brackets ( ) are ___.","answer":"stage directions","explanation":"Brackets show stage directions.","explanation_ar":"الإرشادات المسرحية بين قوسين.","options":["titles","stage directions","captions","labels"],"dok":1,"skill":"drama features"},{"q":"Who says *Vegetables are healthy*?","answer":"Mother","explanation":"Mother says it.","explanation_ar":"الأم.","options":["Mother","Sami","Lama","Grandpa"],"dok":1,"skill":"characters"},{"q":"*Lama: I do not like vegetables!* What comes before the colon?","answer":"the character's name","explanation":"The name shows who speaks.","explanation_ar":"اسم الشخصية.","options":["a stage direction","the title","a question","the character's name"],"dok":1,"skill":"drama features"},{"q":"What do Sami and Lama do before eating?","answer":"They wash their hands.","explanation":"Stage direction: (Sami and Lama wash their hands.)","explanation_ar":"يغسلان أيديهما.","options":["They wash their hands.","They play outside.","They go to bed.","They read a book."],"dok":1,"skill":"sequence"},{"q":"How does Lama feel at the end?","answer":"happy","explanation":"She is smiling.","explanation_ar":"سعيدة.","options":["happy","angry","hungry","sleepy"],"dok":1,"skill":"character feelings"},{"q":"*They help you grow strong.* What helps you grow strong?","answer":"vegetables","explanation":"*They* = vegetables.","explanation_ar":"الخضراوات.","options":["brackets","the kitchen","vegetables","hands"],"dok":2,"skill":"pronoun reference"},{"q":"Which is a stage direction from the play?","answer":"(smiling)","explanation":"Stage directions are in brackets.","explanation_ar":"بين قوسين.","options":["I am hungry!","Yum!","(smiling)","What is for lunch?"],"dok":2,"skill":"drama features"},{"q":"What is the big idea of the play?","answer":"Healthy food can taste good.","explanation":"Lama learns vegetables are good.","explanation_ar":"الطعام الصحي يمكن أن يكون لذيذًا.","options":["Kitchens are big.","Milk is white.","Lama is tall.","Healthy food can taste good."],"dok":3,"skill":"theme"},{"q":"Why does Sami say *Look, Lama. You eat vegetables too!*?","answer":"He is surprised that Lama likes them now.","explanation":"Lama said she did not like them, but now she eats them.","explanation_ar":"تفاجأ بأنها أكلتها.","options":["He wants her vegetables.","He is angry.","He is surprised that Lama likes them now.","He is going to school."],"dok":3,"skill":"inference"}],"images":[{"id":"IMG-RW-L01-U5-LS2-V01","prompt":"Picture for the word 'play': children acting on a small stage with simple props"},{"id":"IMG-RW-L01-U5-LS2-V02","prompt":"Picture for the word 'lines': a script page with names and lines highlighted"},{"id":"IMG-RW-L01-U5-LS2-V03","prompt":"Picture for the word 'stage directions': a script with words in brackets highlighted"},{"id":"IMG-RW-L01-U5-LS2-V04","prompt":"Picture for the word 'strong': a child lifting a big box easily"},{"id":"IMG-RW-L01-U5-LS2-V05","prompt":"Picture for the word 'grow': a seedling growing into a plant in three steps"},{"id":"IMG-RW-L01-U5-LS2-V06","prompt":"Picture for the word 'ready': a child at a table with a napkin, smiling"},{"id":"IMG-RW-L01-U5-LS2-V07","prompt":"Picture for the word 'smiling': a little girl smiling at a plate of food"},{"id":"IMG-RW-L01-U5-LS2-01","prompt":"Mother serves lunch; Lama looks cross, then smiles."},{"id":"IMG-RW-L01-U5-LS2-02","prompt":"A play script with names, lines and stage directions in colors."},{"id":"IMG-RW-L01-U5-LS2-03","prompt":"A die with six feeling faces."}],"audio":[{"id":"AUD-RW-L01-U5-LS2-V01","script":"play. Our class acts a play."},{"id":"AUD-RW-L01-U5-LS2-V02","script":"lines. Learn your lines for the play."},{"id":"AUD-RW-L01-U5-LS2-V03","script":"stage directions. The stage directions say: (smiling)."},{"id":"AUD-RW-L01-U5-LS2-V04","script":"strong. Milk helps you grow strong."},{"id":"AUD-RW-L01-U5-LS2-V05","script":"grow. Plants grow in the sun."},{"id":"AUD-RW-L01-U5-LS2-V06","script":"ready. I am ready to eat."},{"id":"AUD-RW-L01-U5-LS2-V07","script":"smiling. Lama is smiling."},{"id":"AUD-RW-L01-U5-LS2-T1","script":"*Characters: Sami, Mother, Lama* *(The kitchen. Sami and Lama come in.)* **Sami:** I am hungry! What is for lunch? **Mother:** Rice, chicken and vegetables. **Lama:** I do not like vegetables! **Mother:** Vegetables are healthy. They help you grow strong. **Sami:** Can we have dates and milk too? **Mother:** Yes! But first, wash your hands. *(Sami and Lama wash their hands.)* **Lama:** Now I am ready. Yum! Rice and chicken! **Sami:** Look, Lama. You eat vegetables too! **Lama:** *(smiling)* They are good!"},{"id":"AUD-RW-L01-U5-LS2-VID","script":"A play is a story we act! Look: names, lines and stage directions. Sami: I am hungry! What is for lunch? Mother: Rice, chicken and vegetables… The words in brackets are stage directions. We do them. We don't say them! Look at Lama. First: 'I do not like vegetables!' Last: 'They are good!' Lama changes! Now you act it! Read your lines with feeling."}]},{"id":"RW-L01-U5-LS3","title":"Compare: same and different: \"Dates Are the Best!\"","lesson_type":"strategy_paired_text","objectives":["compare two texts: say how they are the same and how they are different","use a Venn diagram to sort same and different details","find the writer's opinion and reasons in a short opinion text"],"objectives_ar":["مقارنة نصين: قول أوجه التشابه والاختلاف.","استخدام شكل فن لتصنيف التفاصيل المتشابهة والمختلفة.","إيجاد رأي الكاتب وأسبابه في نص رأي قصير."],"success_criteria":["I can say how two texts are the same.","I can say how two texts are different.","I can find the opinion and the reasons."],"success_criteria_ar":["أستطيع قول أوجه التشابه بين نصين.","أستطيع قول أوجه الاختلاف بين نصين.","أستطيع إيجاد الرأي والأسباب."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"compare","pos":"verb","ipa":"/kəmˈpɛr/","definition":"to look at how things are the same and different","arabic":"يقارن","example":"Compare the two pictures.","image_id":"IMG-RW-L01-U5-LS3-V01","audio_id":"AUD-RW-L01-U5-LS3-V01","tier":"core"},{"word":"opinion","pos":"noun","ipa":"/əˈpɪnjən/","definition":"what you think or feel about something","arabic":"رأي","example":"My opinion is that dates are the best.","image_id":"IMG-RW-L01-U5-LS3-V02","audio_id":"AUD-RW-L01-U5-LS3-V02","tier":"core"},{"word":"I think","pos":"phrase","ipa":"/aɪ θɪŋk/","definition":"words we use to give an opinion","arabic":"أعتقد / أرى","example":"I think apples are sweet.","image_id":"IMG-RW-L01-U5-LS3-V03","audio_id":"AUD-RW-L01-U5-LS3-V03","tier":"core"},{"word":"best","pos":"adjective","ipa":"/bɛst/","definition":"better than all the others","arabic":"الأفضل","example":"This is the best day!","image_id":"IMG-RW-L01-U5-LS3-V04","audio_id":"AUD-RW-L01-U5-LS3-V04","tier":"core"},{"word":"sweet","pos":"adjective","ipa":"/swit/","definition":"tasting like sugar","arabic":"حلو المذاق","example":"Dates are sweet.","image_id":"IMG-RW-L01-U5-LS3-V05","audio_id":"AUD-RW-L01-U5-LS3-V05","tier":"core"},{"word":"energy","pos":"noun","ipa":"/ˈɛnərdʒi/","definition":"the power to move, play and learn","arabic":"طاقة","example":"Breakfast gives me energy.","image_id":"IMG-RW-L01-U5-LS3-V06","audio_id":"AUD-RW-L01-U5-LS3-V06","tier":"core"},{"word":"because","pos":"conjunction","ipa":"/bɪˈkɔz/","definition":"a word that gives a reason","arabic":"لأن","example":"I like milk because it is cold.","image_id":"IMG-RW-L01-U5-LS3-V07","audio_id":"AUD-RW-L01-U5-LS3-V07","tier":"core"}],"explanation":{"text":"When we **compare** two texts, we look for what is the **same** and what is **different**.\n\nUse a **Venn diagram**: two circles that overlap. Write things that are only in Text 1 in the left circle, only in Text 2 in the right circle, and things in **both** in the middle.\n\n*Dates Are the Best!* is an **opinion** text. The writer says what she **thinks** (*I think…*) and gives **reasons** (*First…, Next…, Last…*).","examples":["Same: Both texts are about **food**.","Same: Both texts say food is **healthy**.","Same: Both texts talk about **dates and milk**.","Different: *What Is for Lunch?* is a **play**; *Dates Are the Best!* is an **opinion** text.","Different: The play has **characters** and **stage directions**; the opinion text has **I think** and **reasons**.","Different: The play is about **rice, chicken and vegetables**; the opinion text is about **dates**.","Opinion: **I think dates are the best food.**","Reason 1: **Dates are sweet and yummy.** Reason 2: **They are healthy.**","Reason 3: **Dates grow on palm trees in Saudi Arabia.**"],"common_errors":["✗ The two texts is same. → ✓ The two texts are the same. (Use **are the same**.)","✗ It is different from the play is about food. → ✓ It is different from the play. The play is about lunch. (Use two clear sentences.)","✗ I am think dates are good. → ✓ I think dates are good. (No **am** before think.)","✗ Dates are the more best. → ✓ Dates are the best. (Just say **the best**.)","✗ Both text are about food. → ✓ Both texts are about food. (After both, use **-s**.)","✗ Because they are sweet. (alone) → ✓ I like dates because they are sweet. (Join the reason to the opinion.)"],"arabic":"عندما نقارن نصين نبحث عمّا هو متشابه وما هو مختلف.\n\nنستخدم شكل فن: دائرتان متداخلتان؛ نكتب ما يخص النص الأول في الدائرة اليسرى، وما يخص النص الثاني في الدائرة اليمنى، وما يشتركان فيه في الوسط.\n\nنص (Dates Are the Best!) نص رأي: الكاتبة تقول ما تعتقده (I think) وتذكر أسبابها (First, Next, Last).\n\nانتبه: نقول I think ولا نقول I am think."},"video":{"script":[{"time":"00:00–00:15","narration":"Two texts about food! Are they the same or different? Let's compare!","on_screen":"Compare 🔍","visual":"The play script and Noura's page fly in side by side."},{"time":"00:15–00:50","narration":"I think dates are the best food. First, dates are sweet and yummy…","on_screen":"(Noura's opinion text)","visual":"Noura reads beside a palm tree; 'I think' glows; First/Next/Last appear as steps."},{"time":"00:50–01:20","narration":"Look! Two circles. This one is the play. This one is Noura's text. The middle is for BOTH.","on_screen":"Venn diagram ⚪⚪","visual":"Two circles overlap; the middle glows gold."},{"time":"01:20–01:50","narration":"Same: both are about food. Both talk about dates and milk. Put them in the middle!","on_screen":"Same → middle","visual":"Food icons slide into the middle."},{"time":"01:50–02:15","narration":"Different: the play has characters. Noura's text has I think and reasons.","on_screen":"Different → sides","visual":"A mask icon goes left; a thought bubble goes right."},{"time":"02:15–02:30","narration":"Same in the middle, different on the sides. You can compare!","on_screen":"Same · Different","visual":"Saqr draws two circles in the sand with his claw."}],"captions_ar":["نصان عن الطعام! هل هما متشابهان أم مختلفان؟ لنقارن!","أعتقد أن التمر أفضل طعام. أولًا، التمر حلو ولذيذ…","انظروا! دائرتان: هذه للمسرحية، وهذه لنص نورة، والوسط لما يشتركان فيه.","التشابه: كلاهما عن الطعام، وكلاهما يذكر التمر والحليب. ضعوهما في الوسط!","الاختلاف: المسرحية فيها شخصيات، ونص نورة فيه I think وأسباب.","المتشابه في الوسط، والمختلف على الجانبين. تستطيع المقارنة!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Noura: confident, friendly girl voice reading her opinion."},"texts":[{"type":"reading","title":"Dates Are the Best!","body":"by Noura\n\nI think dates are the best food. First, dates are sweet and yummy. Next, they are healthy. They give you energy for school.\n\nLast, dates grow on palm trees in Saudi Arabia, so they are our food! Eat dates with milk. You will love them!","word_count":47,"audio_id":"AUD-RW-L01-U5-LS3-T1","id":"TXT-RW-L01-U5-LS3-1","genre":"opinion/argument","role":"paired","difficulty":"BR–200L","glossary":[{"word":"yummy","definition":"very good to eat","arabic":"لذيذ"},{"word":"energy","definition":"the power to move, play and learn","arabic":"طاقة"}]}],"activities":[{"id":"RW-L01-U5-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *Dates Are the Best!* Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"Who wrote *Dates Are the Best!*?","answer":"Noura","explanation":"by Noura","explanation_ar":"كتبته نورة.","options":["Sami","Lama","Mother","Noura"],"dok":1,"skill":"key details","text_id":"TXT-RW-L01-U5-LS3-1","stage":"controlled"},{"q":"What is Noura's opinion?","answer":"Dates are the best food.","explanation":"I think dates are the best food.","explanation_ar":"التمر أفضل طعام.","options":["Milk is cold.","Vegetables are bad.","Rice is sweet.","Dates are the best food."],"dok":1,"skill":"opinion","stage":"controlled"},{"q":"What is reason 1?","answer":"Dates are sweet and yummy.","explanation":"First, dates are sweet and yummy.","explanation_ar":"حلو ولذيذ.","options":["Dates are small.","Dates are sweet and yummy.","Dates are brown.","Dates are hard."],"dok":1,"skill":"reasons","stage":"controlled"},{"q":"What do dates give you?","answer":"energy for school","explanation":"They give you energy for school.","explanation_ar":"طاقة للمدرسة.","options":["energy for school","a new bag","long hair","a big house"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where do dates grow?","answer":"on palm trees","explanation":"Text: on palm trees.","explanation_ar":"على النخيل.","options":["under the sea","on palm trees","in the kitchen","on rocks"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"What does Noura say to eat with dates?","answer":"milk","explanation":"Eat dates with milk.","explanation_ar":"مع الحليب.","options":["rice","chicken","milk","bread"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U5-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Compare the play and Noura's text. Choose the answer.","instructions_ar":"قارن بين المسرحية ونص نورة.","items":[{"q":"How are the two texts the SAME?","answer":"Both are about food.","explanation":"Food is in both.","explanation_ar":"كلاهما عن الطعام.","options":["Both have stage directions.","Both say *I think*.","Both are about camels.","Both are about food."],"dok":1,"skill":"compare: same","stage":"guided"},{"q":"Which food is in BOTH texts?","answer":"dates","explanation":"Sami asks for dates; Noura writes about dates.","explanation_ar":"التمر في كليهما.","options":["dates","rice","chicken","vegetables"],"dok":2,"skill":"compare: same","stage":"guided"},{"q":"What does ONLY the play have?","answer":"characters and stage directions","explanation":"Plays have characters and stage directions.","explanation_ar":"المسرحية فقط فيها شخصيات وإرشادات.","options":["the words *I think*","characters and stage directions","three reasons","palm trees"],"dok":1,"skill":"compare: different","stage":"guided"},{"q":"What does ONLY Noura's text have?","answer":"an opinion with reasons","explanation":"Opinion texts give reasons.","explanation_ar":"نص الرأي فقط فيه رأي وأسباب.","options":["an opinion with reasons","a kitchen","Mother's lines","stage directions"],"dok":1,"skill":"compare: different","stage":"guided"},{"q":"Which word do BOTH texts say about food?","answer":"healthy","explanation":"Mother: healthy. Noura: healthy.","explanation_ar":"كلاهما يقول healthy.","options":["cross","healthy","tiny","slow"],"dok":2,"skill":"compare: same","stage":"guided"},{"q":"Where do you write a detail that is in both texts?","answer":"in the middle of the Venn diagram","explanation":"The middle is for both.","explanation_ar":"في الوسط.","options":["in the left circle","in the right circle","in the middle of the Venn diagram","outside the circles"],"dok":1,"skill":"organizer","stage":"guided"}]},{"id":"RW-L01-U5-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Venn diagram.","instructions_ar":"أكمل شكل فن.","items":[{"q":"Write two things ONLY in the play.","answer":"characters, stage directions","explanation":"Two play features or foods.","explanation_ar":"شيئان في المسرحية فقط.","dok":1,"skill":"compare","stage":"freer"},{"q":"Write two things ONLY in Noura's text.","answer":"I think, palm trees","explanation":"Two details.","explanation_ar":"تفصيلان.","dok":1,"skill":"compare","stage":"freer"},{"q":"Write two things in BOTH texts.","answer":"food, dates and milk","explanation":"Two shared details.","explanation_ar":"تفصيلان مشتركان.","dok":2,"skill":"compare","stage":"freer"},{"q":"Write one sentence: Both texts are about ___.","answer":"Both texts are about healthy food.","explanation":"A sentence with Both.","explanation_ar":"جملة بكلمة Both.","dok":2,"skill":"compare","stage":"freer"}]},{"id":"RW-L01-U5-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write your opinion.","instructions_ar":"اكتب رأيك.","items":[{"q":"What is the best food? Write: I think ___ is/are the best food.","answer":"I think rice is the best food.","explanation":"An opinion with I think.","explanation_ar":"رأي بـ I think.","dok":1,"skill":"opinion","stage":"production"},{"q":"Write one reason.","answer":"It is yummy.","explanation":"A reason.","explanation_ar":"سبب.","dok":2,"skill":"reasons","stage":"production"},{"q":"Write a second reason.","answer":"It gives me energy.","explanation":"Another reason.","explanation_ar":"سبب آخر.","dok":2,"skill":"reasons","stage":"production"},{"q":"Which text do you like more, the play or Noura's text? Why?","answer":"I like the play because I like Lama.","explanation":"Choice + because.","explanation_ar":"اختيار + because.","dok":3,"skill":"evaluate","stage":"production"}]},{"id":"RW-L01-U5-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Dates Are the Best!\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Dates Are the Best!”.","answer":"47 words","title":"Dates Are the Best!","body":"by Noura\n\nI think dates are the best food. First, dates are sweet and yummy. Next, they are healthy. They give you energy for school.\n\nLast, dates grow on palm trees in Saudi Arabia, so they are our food! Eat dates with milk. You will love them!","words":47,"limit":85}],"time_limit_sec":85},{"id":"RW-L01-U5-LS3-ORG","type":"organizer","organizer":"Venn Diagram","instructions":"Organizer: Write details only in the play on the left, only in Noura's text on the right, and in both texts in the middle.","items":[{"q":"Only in *What Is for Lunch?*","answer":"characters, stage directions, rice and chicken"},{"q":"In BOTH texts","answer":"about food; healthy; dates and milk"},{"q":"Only in *Dates Are the Best!*","answer":"I think; three reasons; palm trees"}]}],"game":{"name":"Venn Hoop Jump","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Venn sort: detail tiles fall; the child drags each into the left circle, right circle or the middle. Correct = the tile clicks in; a full diagram unlocks a 'Compare Champion' badge.","Two overlapping hoops on the floor: left = play, right = Noura's text, middle = both.","The teacher reads a detail card.","A student from each team jumps into the right space.","Correct = 1 point.","Play 10 cards; teams take turns."],"data":[]},"exit_quiz":[{"q":"*Compare* means ___.","answer":"find what is the same and different","explanation":"Compare = same and different.","explanation_ar":"المقارنة: التشابه والاختلاف.","options":["write a play","eat dates","read fast","find what is the same and different"],"dok":1,"skill":"strategy"},{"q":"In a Venn diagram, the middle is for things that are ___.","answer":"in both","explanation":"The middle = both.","explanation_ar":"الوسط للمشترك.","options":["only in text 1","only in text 2","not in any text","in both"],"dok":1,"skill":"organizer"},{"q":"Which words show an opinion?","answer":"I think","explanation":"I think = opinion.","explanation_ar":"I think تدل على رأي.","options":["I think","First, open","The kitchen","(smiling)"],"dok":1,"skill":"opinion"},{"q":"What is Noura's second reason?","answer":"Dates are healthy.","explanation":"Next, they are healthy.","explanation_ar":"السبب الثاني: صحية.","options":["Dates are sweet.","Dates grow on palm trees.","Dates are cheap.","Dates are healthy."],"dok":2,"skill":"reasons"},{"q":"How are the two texts different?","answer":"One is a play and one is an opinion text.","explanation":"Different genres.","explanation_ar":"نوعان مختلفان.","options":["Both are plays.","Both are about camels.","One is a play and one is an opinion text.","They are not different."],"dok":1,"skill":"compare: different"},{"q":"Which detail is the SAME in both texts?","answer":"Food is healthy.","explanation":"Both say food is healthy.","explanation_ar":"كلاهما يقول إن الطعام صحي.","options":["Lama is cross.","Dates grow on palm trees.","Food is healthy.","The kitchen is big."],"dok":2,"skill":"compare: same"},{"q":"*Dates are sweet.* *Sweet* means ___.","answer":"tasting like sugar","explanation":"Sweet = like sugar.","explanation_ar":"حلو المذاق.","options":["tasting like sugar","very big","very fast","not clean"],"dok":1,"skill":"vocabulary"},{"q":"Why does Noura say dates are *our food*?","answer":"They grow in Saudi Arabia.","explanation":"Text: they grow … in Saudi Arabia, so they are our food.","explanation_ar":"لأنها تنمو في السعودية.","options":["They are in the play.","They grow in Saudi Arabia.","They are expensive.","They are vegetables."],"dok":2,"skill":"reasons"},{"q":"Which sentence compares the two texts?","answer":"Both texts talk about dates and milk.","explanation":"It says what both have.","explanation_ar":"تذكر ما يشتركان فيه.","options":["I like milk.","Lama is little.","Both texts talk about dates and milk.","Dates are brown."],"dok":2,"skill":"compare"},{"q":"Noura ends with *You will love them!* Why?","answer":"to make the reader want to eat dates","explanation":"She wants readers to agree.","explanation_ar":"لتقنع القارئ بأكل التمر.","options":["to give a stage direction","to make the reader want to eat dates","to name a character","to ask a question"],"dok":3,"skill":"author's purpose"}],"images":[{"id":"IMG-RW-L01-U5-LS3-V01","prompt":"Picture for the word 'compare': two pictures side by side with a magnifying glass between them"},{"id":"IMG-RW-L01-U5-LS3-V02","prompt":"Picture for the word 'opinion': a child with a thought bubble showing a heart and a date"},{"id":"IMG-RW-L01-U5-LS3-V03","prompt":"Picture for the word 'I think': a child pointing to her head while smiling"},{"id":"IMG-RW-L01-U5-LS3-V04","prompt":"Picture for the word 'best': a gold medal"},{"id":"IMG-RW-L01-U5-LS3-V05","prompt":"Picture for the word 'sweet': a date with tiny sparkles"},{"id":"IMG-RW-L01-U5-LS3-V06","prompt":"Picture for the word 'energy': a child running with a small lightning bolt icon"},{"id":"IMG-RW-L01-U5-LS3-V07","prompt":"Picture for the word 'because': a speech bubble with an arrow from a reason"},{"id":"IMG-RW-L01-U5-LS3-01","prompt":"Noura sits under a palm tree with dates and milk."},{"id":"IMG-RW-L01-U5-LS3-02","prompt":"Two overlapping circles for comparing."},{"id":"IMG-RW-L01-U5-LS3-03","prompt":"An apple and a date side by side."}],"audio":[{"id":"AUD-RW-L01-U5-LS3-V01","script":"compare. Compare the two pictures."},{"id":"AUD-RW-L01-U5-LS3-V02","script":"opinion. My opinion is that dates are the best."},{"id":"AUD-RW-L01-U5-LS3-V03","script":"I think. I think apples are sweet."},{"id":"AUD-RW-L01-U5-LS3-V04","script":"best. This is the best day!"},{"id":"AUD-RW-L01-U5-LS3-V05","script":"sweet. Dates are sweet."},{"id":"AUD-RW-L01-U5-LS3-V06","script":"energy. Breakfast gives me energy."},{"id":"AUD-RW-L01-U5-LS3-V07","script":"because. I like milk because it is cold."},{"id":"AUD-RW-L01-U5-LS3-T1","script":"by Noura I think dates are the best food. First, dates are sweet and yummy. Next, they are healthy. They give you energy for school. Last, dates grow on palm trees in Saudi Arabia, so they are our food! Eat dates with milk. You will love them!"},{"id":"AUD-RW-L01-U5-LS3-VID","script":"Two texts about food! Are they the same or different? Let's compare! I think dates are the best food. First, dates are sweet and yummy… Look! Two circles. This one is the play. This one is Noura's text. The middle is for BOTH. Same: both are about food. Both talk about dates and milk. Put them in the middle! Different: the play has characters. Noura's text has I think and reasons. Same in the middle, different on the sides. You can compare!"}]},{"id":"RW-L01-U5-LS4","title":"Writing Skill: Joining words with and","lesson_type":"writing_skill","objectives":["use *and* to join two naming words, two describing words or two action words","join two short sentences with *and* when they belong together","write *and* as a separate word with spaces (not joined like Arabic و)"],"objectives_ar":["استخدام and لربط اسمين أو صفتين أو فعلين.","ربط جملتين قصيرتين بـ and عندما تتصلان معًا.","كتابة and كلمة مستقلة بمسافات (لا تُلصق مثل الواو العربية)."],"success_criteria":["I can join two words with and.","I can join two short sentences with and.","I can leave a space before and after and."],"success_criteria_ar":["أستطيع ربط كلمتين بـ and.","أستطيع ربط جملتين قصيرتين بـ and.","أستطيع ترك مسافة قبل and وبعدها."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"and","pos":"conjunction","ipa":"/ænd/","definition":"a joining word that adds one more thing","arabic":"و (حرف عطف)","example":"I like milk and dates.","image_id":"IMG-RW-L01-U5-LS4-V01","audio_id":"AUD-RW-L01-U5-LS4-V01","tier":"core"},{"word":"cheese","pos":"noun","ipa":"/tʃiz/","definition":"a food made from milk","arabic":"جبن","example":"I have bread and cheese.","image_id":"IMG-RW-L01-U5-LS4-V02","audio_id":"AUD-RW-L01-U5-LS4-V02","tier":"core"},{"word":"juice","pos":"noun","ipa":"/dʒus/","definition":"a drink made from fruit","arabic":"عصير","example":"Orange juice is sweet.","image_id":"IMG-RW-L01-U5-LS4-V03","audio_id":"AUD-RW-L01-U5-LS4-V03","tier":"core"},{"word":"snack","pos":"noun","ipa":"/snæk/","definition":"a small food between meals","arabic":"وجبة خفيفة","example":"An apple is a good snack.","image_id":"IMG-RW-L01-U5-LS4-V04","audio_id":"AUD-RW-L01-U5-LS4-V04","tier":"core"},{"word":"yummy","pos":"adjective","ipa":"/ˈjʌmi/","definition":"very good to eat","arabic":"لذيذ","example":"This soup is yummy.","image_id":"IMG-RW-L01-U5-LS4-V05","audio_id":"AUD-RW-L01-U5-LS4-V05","tier":"core"},{"word":"lunch box","pos":"noun","ipa":"/ˈlʌntʃ bɑks/","definition":"a box to carry your lunch","arabic":"علبة الغداء","example":"My lunch box is blue.","image_id":"IMG-RW-L01-U5-LS4-V06","audio_id":"AUD-RW-L01-U5-LS4-V06","tier":"core"},{"word":"salad","pos":"noun","ipa":"/ˈsæləd/","definition":"cold mixed vegetables","arabic":"سلطة","example":"We eat salad with rice.","image_id":"IMG-RW-L01-U5-LS4-V07","audio_id":"AUD-RW-L01-U5-LS4-V07","tier":"core"}],"explanation":{"text":"**And** is a **joining word**. It joins two things that go together.\n\nJoin two **naming words**: *milk **and** dates*. Join two **describing words**: *sweet **and** healthy*. Join two **action words**: *wash **and** eat*.\n\nJoin two short **sentences**: *I am hungry. I want lunch.* → *I am hungry **and** I want lunch.*\n\nIn Arabic, و joins onto the next word (والتمر). In English, **and** is a separate word with a **space** before and after it.","examples":["I like milk **and** dates.","I have bread **and** cheese.","Sami eats rice **and** chicken.","The apple is red **and** sweet.","Dates are yummy **and** healthy.","We wash **and** eat.","I drink juice **and** water.","Lama is hungry **and** she wants lunch.","My lunch box has a banana **and** a salad."],"common_errors":["✗ I like milkanddates. → ✓ I like milk and dates. (Leave spaces: **and** is a separate word.)","✗ I like milk, dates. → ✓ I like milk and dates. (Use **and** to join the last two words.)","✗ I like milk and I like dates and I like bread and… → ✓ I like milk, dates and bread. (Do not use **and** too many times.)","✗ And I eat rice. → ✓ I eat rice and chicken. (Do not start every sentence with **And**.)","✗ I eat an apple and banana. → ✓ I eat an apple and a banana. (Keep **a** before banana.)","✗ I eat rice and. → ✓ I eat rice and salad. (Something must come after **and**.)"],"arabic":"كلمة and كلمة ربط تجمع شيئين يتناسبان معًا.\n\nتربط اسمين: milk and dates، أو صفتين: sweet and healthy، أو فعلين: wash and eat.\n\nوتربط جملتين قصيرتين: I am hungry and I want lunch.\n\nفي العربية تلتصق الواو بالكلمة التالية (والتمر)، أما في الإنجليزية فـ and كلمة مستقلة نترك قبلها وبعدها مسافة."},"video":{"script":[{"time":"00:00–00:15","narration":"Meet a very helpful word: AND!","on_screen":"and 🔗","visual":"The word 'and' appears as a little chain link with a smile."},{"time":"00:15–00:45","narration":"Milk… dates… Click! Milk and dates!","on_screen":"milk + and + dates","visual":"Two food pictures slide together; 'and' clicks between them."},{"time":"00:45–01:10","narration":"Sweet and healthy. Wash and eat. And joins describing words and action words too!","on_screen":"sweet and healthy · wash and eat","visual":"Word pairs click together in different colors."},{"time":"01:10–01:40","narration":"In Arabic, و sticks to the next word. In English, AND stands alone, with a space on each side!","on_screen":"milkanddates ✗ → milk and dates ✓","visual":"Squashed words pop apart; two little space blocks appear around 'and'."},{"time":"01:40–02:05","narration":"Two short sentences: I am hungry. I want lunch. Click! I am hungry and I want lunch.","on_screen":"join two sentences","visual":"Two sentence strips slide together with 'and' in the middle."},{"time":"02:05–02:20","narration":"Use and to join – but not too many times!","on_screen":"and ✔ (not and and and…)","visual":"Saqr stops a very long train of 'and' cars with a smile."}],"captions_ar":["تعرّفوا على كلمة مفيدة جدًا: and!","حليب… تمر… طَق! حليب وتمر!","حلو وصحي. اغسل وكُل. and تربط الصفات والأفعال أيضًا!","في العربية تلتصق الواو بالكلمة التالية، أما في الإنجليزية فتقف and وحدها بمسافة على كل جانب!","جملتان قصيرتان: أنا جائع. أريد الغداء. طَق! أنا جائع وأريد الغداء.","استخدم and للربط، ولكن لا تكررها كثيرًا!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Sami: cheerful boy. A soft 'click' sound when and joins two words."},"texts":[{"type":"model","title":"My Lunch Box (from Sami's Notebook)","body":"My lunch box has bread and cheese. I have an apple and a banana. I drink water and milk.\n\nI wash my hands and I sit with Omar. My lunch is yummy and healthy!","word_count":34,"audio_id":"AUD-RW-L01-U5-LS4-T1","id":"TXT-RW-L01-U5-LS4-1","genre":"model text","role":"model","difficulty":"BR–200L","glossary":[],"annotations":["bread **and** cheese – *and* joins two food words.","an apple **and** a banana – *and* joins two fruit words (with a and an).","water **and** milk – *and* joins two drink words.","I wash my hands **and** I sit with Omar – *and* joins two short sentences.","yummy **and** healthy – *and* joins two describing words.","*and* is a separate word with a space before and after it."]}],"activities":[{"id":"RW-L01-U5-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct joined words.","instructions_ar":"اختر الكلمات المربوطة بشكل صحيح.","items":[{"q":"Join *bread* and *cheese*.","answer":"bread and cheese","explanation":"And with spaces between two words.","explanation_ar":"and بمسافات.","options":["bread and cheese","breadandcheese","bread, cheese","and bread cheese"],"dok":1,"skill":"joining words","stage":"controlled"},{"q":"Join *sweet* and *healthy*.","answer":"sweet and healthy","explanation":"Two describing words joined by and.","explanation_ar":"صفتان بينهما and.","options":["sweetandhealthy","sweet healthy and","sweet and healthy","and sweet healthy"],"dok":1,"skill":"joining words","stage":"controlled"},{"q":"Join *an apple* and *a banana*.","answer":"an apple and a banana","explanation":"Keep a/an and spaces.","explanation_ar":"مع a/an ومسافات.","options":["an apple and banana a","an apple and a banana","a apple and an banana","an appleand a banana"],"dok":2,"skill":"joining words","stage":"controlled"},{"q":"Join *wash* and *eat*.","answer":"wash and eat","explanation":"Two action words joined by and.","explanation_ar":"فعلان بينهما and.","options":["washandeat","eat wash and","and wash eat","wash and eat"],"dok":1,"skill":"joining words","stage":"controlled"},{"q":"Which sentence joins two sentences correctly?","answer":"I am hungry and I want lunch.","explanation":"Sentence + and + sentence, with spaces.","explanation_ar":"جملة + and + جملة.","options":["I am hungry and.","I am hungry and I want lunch.","And I am hungry I want lunch.","I am hungryand I want lunch."],"dok":2,"skill":"joining sentences","stage":"controlled"},{"q":"Which sentence uses *and* too many times?","answer":"I like milk and I like dates and I like bread and I like rice.","explanation":"Too many and's make it long.","explanation_ar":"تكرار كثير لـ and.","options":["I like milk and I like dates and I like bread and I like rice.","I like milk and dates.","I eat rice and salad.","We wash and eat."],"dok":2,"skill":"style","stage":"controlled"}]},{"id":"RW-L01-U5-LS4-A2","type":"open","stage":"guided","instructions":"Guided practice: Join the two words or sentences with *and*. Write them.","instructions_ar":"اربط الكلمتين أو الجملتين بـ and.","items":[{"q":"juice / water","answer":"juice and water","explanation":"Two drinks joined.","explanation_ar":"مشروبان مربوطان.","dok":1,"skill":"joining words","stage":"guided"},{"q":"rice / salad","answer":"rice and salad","explanation":"Two foods joined.","explanation_ar":"طعامان مربوطان.","dok":1,"skill":"joining words","stage":"guided"},{"q":"red / sweet","answer":"red and sweet","explanation":"Two describing words.","explanation_ar":"صفتان.","dok":1,"skill":"joining words","stage":"guided"},{"q":"a date / an egg","answer":"a date and an egg","explanation":"Keep a and an.","explanation_ar":"احتفظ بـ a وan.","dok":2,"skill":"joining words","stage":"guided"},{"q":"I am thirsty. I want water.","answer":"I am thirsty and I want water.","explanation":"Two sentences joined.","explanation_ar":"جملتان مربوطتان.","dok":2,"skill":"joining sentences","stage":"guided"},{"q":"Omar eats a snack. He drinks milk.","answer":"Omar eats a snack and he drinks milk.","explanation":"Two sentences joined.","explanation_ar":"جملتان مربوطتان.","dok":2,"skill":"joining sentences","stage":"guided"}]},{"id":"RW-L01-U5-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Fix the mistakes.","instructions_ar":"صحّح الأخطاء.","items":[{"q":"I like datesandmilk.","answer":"I like dates and milk.","explanation":"Add spaces around and.","explanation_ar":"أضف مسافات.","dok":2,"skill":"editing","stage":"freer"},{"q":"My lunch box has cheese, bread.","answer":"My lunch box has cheese and bread.","explanation":"Use and.","explanation_ar":"استخدم and.","dok":2,"skill":"editing","stage":"freer"},{"q":"I eat a apple and banana.","answer":"I eat an apple and a banana.","explanation":"an apple; a banana.","explanation_ar":"an apple وa banana.","dok":2,"skill":"editing","stage":"freer"},{"q":"Lama drinks juice and.","answer":"Lama drinks juice and milk.","explanation":"Add a word after and.","explanation_ar":"أضف كلمة بعد and.","dok":2,"skill":"editing","stage":"freer"}]},{"id":"RW-L01-U5-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write about YOUR lunch box. Use *and*.","instructions_ar":"اكتب عن علبة غدائك مستخدمًا and.","items":[{"q":"What food is in your lunch box? Use and.","answer":"My lunch box has bread and cheese.","explanation":"Two foods joined.","explanation_ar":"طعامان مربوطان.","dok":1,"skill":"writing","stage":"production"},{"q":"What fruit do you have? Use and.","answer":"I have dates and a banana.","explanation":"Two fruits.","explanation_ar":"فاكهتان.","dok":1,"skill":"writing","stage":"production"},{"q":"What do you drink? Use and.","answer":"I drink water and juice.","explanation":"Two drinks.","explanation_ar":"مشروبان.","dok":1,"skill":"writing","stage":"production"},{"q":"How is your lunch? Use two describing words with and.","answer":"My lunch is yummy and healthy.","explanation":"Two describing words.","explanation_ar":"صفتان.","dok":2,"skill":"writing","stage":"production"}]}],"game":{"name":"And Chain","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Link builder: two picture tiles appear; the child drags the and-link between them and records or types the phrase. Correct phrases add a link to a growing chain across the screen.","Students sit in a circle. One student holds the 'and' link.","The teacher shows two picture cards.","The student with the link says the phrase (\"milk and dates\") and passes the link.","The next student gets two new cards.","Every correct phrase adds a paper link to the class chain on the wall."],"data":[]},"exit_quiz":[{"q":"*And* is a ___ word.","answer":"joining","explanation":"And joins things.","explanation_ar":"and كلمة ربط.","options":["naming","describing","number","joining"],"dok":1,"skill":"rule"},{"q":"Which phrase is written correctly?","answer":"milk and dates","explanation":"Spaces around and.","explanation_ar":"مسافات حول and.","options":["milk and dates","milkanddates","milk anddates","milkand dates"],"dok":1,"skill":"spacing"},{"q":"Which sentence uses *and* to join two describing words?","answer":"The apple is red and sweet.","explanation":"Red and sweet are describing words.","explanation_ar":"صفتان.","options":["I eat an apple.","Apples are red.","The apple is red and sweet.","I like apples and bananas."],"dok":2,"skill":"joining words"},{"q":"Join: *I am hungry. I want bread.*","answer":"I am hungry and I want bread.","explanation":"Sentence and sentence.","explanation_ar":"جملة and جملة.","options":["I am hungry and.","I am hungry and I want bread.","I want and hungry bread.","And I am hungry."],"dok":2,"skill":"joining sentences"},{"q":"Which is a snack?","answer":"an apple","explanation":"A snack is a small food.","explanation_ar":"الوجبة الخفيفة طعام صغير.","options":["dinner","the kitchen","a lunch box","an apple"],"dok":1,"skill":"vocabulary"},{"q":"Which is a drink made from fruit?","answer":"juice","explanation":"Juice comes from fruit.","explanation_ar":"العصير من الفاكهة.","options":["cheese","salad","juice","bread"],"dok":1,"skill":"vocabulary"},{"q":"In Sami's model, what does his lunch box have?","answer":"bread and cheese","explanation":"My lunch box has bread and cheese.","explanation_ar":"خبز وجبن.","options":["rice and chicken","eggs and juice","bread and cheese","salad and fish"],"dok":1,"skill":"key details"},{"q":"Fix: *I eat a apple and banana.*","answer":"I eat an apple and a banana.","explanation":"an apple; a banana.","explanation_ar":"an apple وa banana.","options":["I eat a apple and a banana.","I eat an apple and a banana.","I eat an apple and banana.","I eat apple and an banana."],"dok":2,"skill":"editing"},{"q":"Why is *and* written with spaces in English?","answer":"It is a separate word.","explanation":"English words stand alone.","explanation_ar":"لأنها كلمة مستقلة.","options":["It is a separate word.","It is a long word.","It is a number.","It is a name."],"dok":2,"skill":"rule"},{"q":"Which sentence sounds best?","answer":"I like rice, salad and chicken.","explanation":"Fewer and's, still clear.","explanation_ar":"أوضح وأقصر.","options":["I like rice and I like salad and I like chicken.","And I like rice. And salad.","I like rice salad chicken.","I like rice, salad and chicken."],"dok":3,"skill":"style"}],"images":[{"id":"IMG-RW-L01-U5-LS4-V01","prompt":"Picture for the word 'and': two puzzle pieces with 'and' as the connector"},{"id":"IMG-RW-L01-U5-LS4-V02","prompt":"Picture for the word 'cheese': a slice of white cheese"},{"id":"IMG-RW-L01-U5-LS4-V03","prompt":"Picture for the word 'juice': a glass of orange juice"},{"id":"IMG-RW-L01-U5-LS4-V04","prompt":"Picture for the word 'snack': a small bowl with apple slices"},{"id":"IMG-RW-L01-U5-LS4-V05","prompt":"Picture for the word 'yummy': a child licking lips next to a bowl of soup"},{"id":"IMG-RW-L01-U5-LS4-V06","prompt":"Picture for the word 'lunch box': an open blue lunch box with sandwich and fruit"},{"id":"IMG-RW-L01-U5-LS4-V07","prompt":"Picture for the word 'salad': a bowl of salad with tomatoes and cucumbers"},{"id":"IMG-RW-L01-U5-LS4-01","prompt":"Sami's lunch box with bread, cheese, fruit, water and milk."},{"id":"IMG-RW-L01-U5-LS4-02","prompt":"A chain link joins a glass of milk and a bowl of dates."},{"id":"IMG-RW-L01-U5-LS4-03","prompt":"Joined Arabic letters next to separate English word blocks."}],"audio":[{"id":"AUD-RW-L01-U5-LS4-V01","script":"and. I like milk and dates."},{"id":"AUD-RW-L01-U5-LS4-V02","script":"cheese. I have bread and cheese."},{"id":"AUD-RW-L01-U5-LS4-V03","script":"juice. Orange juice is sweet."},{"id":"AUD-RW-L01-U5-LS4-V04","script":"snack. An apple is a good snack."},{"id":"AUD-RW-L01-U5-LS4-V05","script":"yummy. This soup is yummy."},{"id":"AUD-RW-L01-U5-LS4-V06","script":"lunch box. My lunch box is blue."},{"id":"AUD-RW-L01-U5-LS4-V07","script":"salad. We eat salad with rice."},{"id":"AUD-RW-L01-U5-LS4-T1","script":"My lunch box has bread and cheese. I have an apple and a banana. I drink water and milk. I wash my hands and I sit with Omar. My lunch is yummy and healthy!"},{"id":"AUD-RW-L01-U5-LS4-VID","script":"Meet a very helpful word: AND! Milk… dates… Click! Milk and dates! Sweet and healthy. Wash and eat. And joins describing words and action words too! In Arabic, و sticks to the next word. In English, AND stands alone, with a space on each side! Two short sentences: I am hungry. I want lunch. Click! I am hungry and I want lunch. Use and to join – but not too many times!"}]},{"id":"RW-L01-U5-LS5","title":"Writing Workshop: My Healthy Lunch","lesson_type":"writing_workshop","objectives":["plan a healthy lunch using the food groups","write a menu card with a title and 4 sentences that use *and*","give one reason why the lunch is healthy, then edit and publish"],"objectives_ar":["التخطيط لغداء صحي باستخدام مجموعات الطعام.","كتابة بطاقة قائمة طعام بعنوان و4 جمل تستخدم and.","ذكر سبب واحد لكون الغداء صحيًا، ثم التدقيق والنشر."],"success_criteria":["I can plan a healthy lunch.","I can write 4 sentences with and.","I can say why my lunch is healthy."],"success_criteria_ar":["أستطيع التخطيط لغداء صحي.","أستطيع كتابة 4 جمل باستخدام and.","أستطيع قول لماذا غدائي صحي."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"menu","pos":"noun","ipa":"/ˈmɛnju/","definition":"a list of the food you can eat","arabic":"قائمة الطعام","example":"Read the menu and choose.","image_id":"IMG-RW-L01-U5-LS5-V01","audio_id":"AUD-RW-L01-U5-LS5-V01","tier":"core"},{"word":"dessert","pos":"noun","ipa":"/dɪˈzɝt/","definition":"sweet food after a meal","arabic":"حلوى (بعد الطعام)","example":"We have fruit for dessert.","image_id":"IMG-RW-L01-U5-LS5-V02","audio_id":"AUD-RW-L01-U5-LS5-V02","tier":"core"},{"word":"fresh","pos":"adjective","ipa":"/frɛʃ/","definition":"new and good; not old","arabic":"طازج","example":"This bread is fresh.","image_id":"IMG-RW-L01-U5-LS5-V03","audio_id":"AUD-RW-L01-U5-LS5-V03","tier":"core"},{"word":"bowl","pos":"noun","ipa":"/boʊl/","definition":"a round deep dish","arabic":"وعاء / سلطانية","example":"I eat soup from a bowl.","image_id":"IMG-RW-L01-U5-LS5-V04","audio_id":"AUD-RW-L01-U5-LS5-V04","tier":"core"},{"word":"glass","pos":"noun","ipa":"/ɡlæs/","definition":"a cup made of glass for drinks","arabic":"كأس","example":"A glass of water, please.","image_id":"IMG-RW-L01-U5-LS5-V05","audio_id":"AUD-RW-L01-U5-LS5-V05","tier":"core"},{"word":"spoon","pos":"noun","ipa":"/spun/","definition":"you eat soup or rice with it","arabic":"ملعقة","example":"Use a spoon for the rice.","image_id":"IMG-RW-L01-U5-LS5-V06","audio_id":"AUD-RW-L01-U5-LS5-V06","tier":"core"},{"word":"half","pos":"noun","ipa":"/hæf/","definition":"one of two equal parts","arabic":"نصف","example":"Fill half your plate with vegetables.","image_id":"IMG-RW-L01-U5-LS5-V07","audio_id":"AUD-RW-L01-U5-LS5-V07","tier":"core"}],"explanation":{"text":"A **menu card** tells what food is in a meal. It has a **title** and short sentences.\n\nWrite four sentences: **main food** (I eat ___ and ___.) · **fruit or dessert** · **drink** (I drink ___.) · **why it is healthy** (It gives me energy.).\n\nUse **and** to join foods. Fill **half** your plate with vegetables and fruit!","examples":["Title: **Noura's Healthy Lunch**","Main food: **I eat rice and chicken.**","Main food: **I have fresh bread and cheese.**","Vegetables: **I eat a bowl of salad.**","Fruit: **For dessert, I eat dates and a banana.**","Drink: **I drink a glass of milk.**","Drink: **I drink water and juice.**","Why: **It is healthy and it gives me energy.**","Why: **Vegetables help me grow strong.**"],"common_errors":["✗ I eat a rice and a chicken. → ✓ I eat rice and chicken. (No **a** before rice or chicken (food).)","✗ For dessert I eat dates. → ✓ For dessert, I eat dates. (Comma after *For dessert*.)","✗ I drink a glass from milk. → ✓ I drink a glass of milk. (Say **a glass of**.)","✗ It give me energy. → ✓ It gives me energy. (It → **gives**.)","✗ My lunch healthy. → ✓ My lunch is healthy. (Do not forget **is**.)","✗ noura's healthy lunch → ✓ Noura's Healthy Lunch (Big words in a title start with capitals.)"],"arabic":"بطاقة قائمة الطعام تخبرنا بما في الوجبة، ولها عنوان وجمل قصيرة.\n\nاكتب أربع جمل: الطعام الرئيسي، والفاكهة أو الحلوى، والمشروب، وسبب كون الوجبة صحية.\n\nاستخدم and لربط الأطعمة، واملأ نصف طبقك بالخضراوات والفاكهة!\n\nانتبه: نقول a glass of milk، ونقول It gives بإضافة s."},"video":{"script":[{"time":"00:00–00:15","narration":"Welcome to Noura's Café! Today you make a healthy menu card.","on_screen":"My Healthy Lunch","visual":"Noura in a small chef's hat behind a pretend café counter."},{"time":"00:15–00:45","narration":"Plan: choose a main food, vegetables, fruit and a drink. Half the plate is vegetables and fruit!","on_screen":"1 Plan 🍽️","visual":"A plate divides in half; vegetables and fruit fill one half; rice and chicken the other."},{"time":"00:45–01:20","narration":"Draft: I eat rice and chicken. I eat a bowl of salad. For dessert, I eat dates. I drink a glass of milk.","on_screen":"2 Draft – food · fruit · drink","visual":"Sentences appear on a menu card; 'and' links glow."},{"time":"01:20–01:45","narration":"Revise: add why! It is healthy and it gives me energy.","on_screen":"3 Revise ➕ why","visual":"A small energy bolt pops next to the new sentence."},{"time":"01:45–02:10","narration":"Edit: capitals in the title, a comma after For dessert, periods. Check!","on_screen":"4 Edit ✔","visual":"Title letters grow into capitals; a comma drops into place."},{"time":"02:10–02:40","narration":"Publish: put your menu in our class café. Read it to a customer!","on_screen":"5 Publish 🧾","visual":"Students stand at the class café, reading menus to each other."}],"captions_ar":["مرحبًا بكم في مقهى نورة! اليوم تصنع بطاقة قائمة طعام صحية.","خطِّط: اختر طعامًا رئيسيًا وخضراوات وفاكهة ومشروبًا. نصف الطبق خضراوات وفاكهة!","المسودة: آكل الأرز والدجاج. آكل وعاء سلطة. وللحلوى آكل التمر. أشرب كأس حليب.","التحسين: أضف السبب! إنه صحي ويعطيني طاقة.","التدقيق: حروف كبيرة في العنوان، وفاصلة بعد For dessert، ونقاط.","النشر: ضع قائمتك في مقهى الفصل واقرأها لزبون!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Noura: friendly girl presenting her café menu like a chef."},"texts":[],"activities":[{"id":"RW-L01-U5-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"A list of food you can choose is a ___.","answer":"menu","explanation":"A menu lists food.","explanation_ar":"قائمة الطعام.","options":["menu","spoon","bowl","glass"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Sweet food after a meal is ___.","answer":"dessert","explanation":"Dessert comes after.","explanation_ar":"الحلوى بعد الطعام.","options":["breakfast","dessert","a spoon","a menu"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"We drink water from a ___.","answer":"glass","explanation":"Drinks go in a glass.","explanation_ar":"نشرب من الكأس.","options":["spoon","glass","bowl","menu"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"How much of your plate should be vegetables and fruit?","answer":"half","explanation":"Half the plate.","explanation_ar":"نصف الطبق.","options":["none","a little spoon","half","all of it"],"dok":1,"skill":"health","stage":"controlled"},{"q":"Which sentence tells WHY a lunch is healthy?","answer":"It gives me energy.","explanation":"It gives a reason.","explanation_ar":"تذكر السبب.","options":["I drink milk.","My plate is blue.","It gives me energy.","I eat at twelve."],"dok":2,"skill":"reasons","stage":"controlled"},{"q":"Which title is written correctly?","answer":"Omar's Healthy Lunch","explanation":"Capitals for the big words.","explanation_ar":"حروف كبيرة للكلمات الأساسية.","options":["omar's healthy lunch","Omar's healthy Lunch","OMAR'S healthy lunch","Omar's Healthy Lunch"],"dok":2,"skill":"titles","stage":"controlled"}]},{"id":"RW-L01-U5-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the words in order.","instructions_ar":"رتّب الكلمات.","items":[{"q":"Build a main-food sentence.","answer":"I eat rice and chicken.","explanation":"Main food sentence.","explanation_ar":"جملة الطعام الرئيسي.","stage":"guided","parts":["eat","chicken.","and","rice","I"],"target":["I","eat","rice","and","chicken."]},{"q":"Build a drink sentence with a glass.","answer":"I drink a glass of milk.","explanation":"a glass of milk.","explanation_ar":"كأس من الحليب.","stage":"guided","parts":["glass","I","a","drink","of","milk."],"target":["I","drink","a","glass","of","milk."]},{"q":"Build a dessert sentence.","answer":"For dessert, I eat dates.","explanation":"For dessert, + sentence.","explanation_ar":"للحلوى + جملة.","stage":"guided","parts":["I","dates.","For","dessert,","eat"],"target":["For","dessert,","I","eat","dates."]},{"q":"Build a sentence about salad.","answer":"I eat a bowl of salad.","explanation":"a bowl of salad.","explanation_ar":"وعاء من السلطة.","stage":"guided","parts":["salad.","bowl","a","of","eat","I"],"target":["I","eat","a","bowl","of","salad."]},{"q":"Build a 'why' sentence about energy.","answer":"It gives me energy.","explanation":"It gives me energy.","explanation_ar":"يعطيني طاقة.","stage":"guided","parts":["gives","It","me","energy."],"target":["It","gives","me","energy."]},{"q":"Build a sentence about fresh bread.","answer":"The bread is fresh and soft.","explanation":"Two describing words with and.","explanation_ar":"صفتان بينهما and.","stage":"guided","parts":["soft.","and","is","The","bread","fresh"],"target":["The","bread","is","fresh","and","soft."]}]},{"id":"RW-L01-U5-LS5-A3","type":"open","stage":"freer","instructions":"Freer practice: Plan your Half-Plate. Write the foods.","instructions_ar":"خطط لطبقك واكتب الأطعمة.","items":[{"q":"Main food:","answer":"rice and fish","explanation":"A main food.","explanation_ar":"طعام رئيسي.","dok":1,"skill":"planning","stage":"freer"},{"q":"Vegetables:","answer":"salad and carrots","explanation":"Vegetables.","explanation_ar":"خضراوات.","dok":1,"skill":"planning","stage":"freer"},{"q":"Fruit or dessert:","answer":"an apple and dates","explanation":"Fruit.","explanation_ar":"فاكهة.","dok":1,"skill":"planning","stage":"freer"},{"q":"Drink:","answer":"water","explanation":"A drink.","explanation_ar":"مشروب.","dok":1,"skill":"planning","stage":"freer"}]},{"id":"RW-L01-U5-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your menu card. Then edit and publish.","instructions_ar":"اكتب بطاقة القائمة ثم دققها وانشرها.","items":[{"q":"Write your title and your main-food sentence.","answer":"Badr's Healthy Lunch. I eat rice and fish.","explanation":"Title + sentence.","explanation_ar":"عنوان + جملة.","dok":1,"skill":"writing","stage":"production"},{"q":"Write your vegetable or fruit sentence and your drink sentence.","answer":"For dessert, I eat an apple. I drink water.","explanation":"Two sentences.","explanation_ar":"جملتان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write why your lunch is healthy.","answer":"It is healthy and it helps me grow strong.","explanation":"A reason.","explanation_ar":"سبب.","dok":2,"skill":"writing","stage":"production"},{"q":"At the class café, what did your customer choose?","answer":"He chose rice and fish.","explanation":"One sentence.","explanation_ar":"جملة واحدة.","dok":2,"skill":"sharing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L01-U5-LS5-ORG","type":"organizer","organizer":"Half-Plate Plan","instructions":"Organizer: Draw your lunch on the plate. Half is vegetables and fruit. Write the foods.","items":[{"q":"Main food (rice, bread, chicken, egg)","answer":"rice and chicken"},{"q":"Vegetables","answer":"salad"},{"q":"Fruit or dessert","answer":"dates and a banana"},{"q":"Drink","answer":"milk"}]},{"id":"RW-L01-U5-LS5-WR","type":"writing","instructions":"Writing: Write a healthy menu card: a title and 4 sentences about your lunch. Use and. Write a healthy menu card: a title and 4 sentences about your lunch. Use and.","instructions_ar":"اكتب بطاقة قائمة طعام صحية: عنوانًا و4 جمل عن غدائك، واستخدم and.","prompt":"Write a healthy menu card: a title and 4 sentences about your lunch. Use and.","checklist":["My menu has a title with capital letters.","I wrote about a main food, fruit or vegetables, and a drink.","I used and to join two foods.","I wrote why my lunch is healthy.","Every sentence has a capital letter and a period.","and has a space before and after it."],"rubric_id":"RW-RUBRIC-5T","min_words":18,"max_words":55,"organizer":"Half-Plate Plan (main food – vegetables – fruit – drink)","items":[{"q":"Write a healthy menu card: a title and 4 sentences about your lunch. Use and.","answer":"Noura's Healthy Lunch. I eat rice and chicken. I eat a bowl of fresh salad. For dessert, I eat dates and a banana. I drink a glass of milk. It is healthy and it gives me energy.","_w":{"checklist":["My menu has a title with capital letters.","I wrote about a main food, fruit or vegetables, and a drink.","I used and to join two foods.","I wrote why my lunch is healthy.","Every sentence has a capital letter and a period.","and has a space before and after it."],"min":18,"max":55}}]}],"game":{"name":"Build a Healthy Plate","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Plate builder: drag foods onto a plate split in half. The plate's 'health meter' fills when half is vegetables and fruit and there is a drink. Then the child records a sentence with and.","Each pair gets a paper plate and 10 food cards.","In 2 minutes, they build a healthy plate: half vegetables and fruit, a main food and a drink.","They say their plate with and: \"Rice and chicken, salad and dates, and water!\"","The judge (a student) checks the list.","A full healthy plate = 3 points."],"data":[]},"exit_quiz":[{"q":"What does a menu card tell you?","answer":"what food is in a meal","explanation":"Menus list food.","explanation_ar":"القائمة تذكر الطعام.","options":["how animals move","where a story happens","what food is in a meal","who wrote a note"],"dok":1,"skill":"genre"},{"q":"Which sentence is a drink sentence?","answer":"I drink a glass of juice.","explanation":"It tells the drink.","explanation_ar":"جملة المشروب.","options":["I drink a glass of juice.","I eat salad.","It gives me energy.","Lunch is at twelve."],"dok":1,"skill":"sentence types"},{"q":"Which phrase about a drink is correct?","answer":"a glass of milk","explanation":"Say *a glass of*.","explanation_ar":"a glass of.","options":["a glass of milk","a glass from milk","a milk glass of","glass a milk"],"dok":2,"skill":"usage"},{"q":"*Fresh* bread is ___.","answer":"new and good","explanation":"Fresh = new and good.","explanation_ar":"طازج.","options":["old and hard","very sweet","very cold","new and good"],"dok":1,"skill":"vocabulary"},{"q":"Where does the comma go in the dessert sentence?","answer":"For dessert, I eat dates.","explanation":"After *For dessert*.","explanation_ar":"بعد For dessert.","options":["For, dessert I eat dates.","For dessert I, eat dates.","For dessert I eat, dates.","For dessert, I eat dates."],"dok":2,"skill":"punctuation"},{"q":"Which lunch is the most healthy?","answer":"rice, salad, dates and water","explanation":"It has all the groups.","explanation_ar":"فيه كل المجموعات.","options":["rice, salad, dates and water","chips, candy and soda","cake and juice","only bread"],"dok":2,"skill":"health"},{"q":"Which word means *one of two equal parts*?","answer":"half","explanation":"Half = one of two parts.","explanation_ar":"نصف.","options":["bowl","spoon","menu","half"],"dok":1,"skill":"vocabulary"},{"q":"Which reason tells why food is healthy?","answer":"Vegetables help me grow strong.","explanation":"It explains the health benefit.","explanation_ar":"توضح الفائدة الصحية.","options":["My plate is round.","Vegetables help me grow strong.","I like the color red.","The café is big."],"dok":2,"skill":"reasons"},{"q":"Fix: *It give me energy.*","answer":"It gives me energy.","explanation":"It → gives.","explanation_ar":"It gives.","options":["It giving me energy.","It is give me energy.","It gives me energy.","It gives me a energy."],"dok":2,"skill":"editing"},{"q":"Which menu card is the best?","answer":"a title, four sentences with and, and a reason","explanation":"It has all the parts.","explanation_ar":"فيها كل الأجزاء.","options":["a title only","a title, four sentences with and, and a reason","a picture only","one word"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L01-U5-LS5-V01","prompt":"Picture for the word 'menu': a café menu card with pictures of dishes"},{"id":"IMG-RW-L01-U5-LS5-V02","prompt":"Picture for the word 'dessert': a bowl of fruit salad"},{"id":"IMG-RW-L01-U5-LS5-V03","prompt":"Picture for the word 'fresh': fresh bread with steam rising"},{"id":"IMG-RW-L01-U5-LS5-V04","prompt":"Picture for the word 'bowl': a bowl of soup"},{"id":"IMG-RW-L01-U5-LS5-V05","prompt":"Picture for the word 'glass': a glass of water"},{"id":"IMG-RW-L01-U5-LS5-V06","prompt":"Picture for the word 'spoon': a spoon next to a plate of rice"},{"id":"IMG-RW-L01-U5-LS5-V07","prompt":"Picture for the word 'half': a plate divided in half with vegetables on one side"},{"id":"IMG-RW-L01-U5-LS5-01","prompt":"A class café with menu cards, Noura and Sami."},{"id":"IMG-RW-L01-U5-LS5-02","prompt":"A plate: half vegetables and fruit, half rice and chicken."},{"id":"IMG-RW-L01-U5-LS5-03","prompt":"An empty menu card with a palm-leaf border."}],"audio":[{"id":"AUD-RW-L01-U5-LS5-V01","script":"menu. Read the menu and choose."},{"id":"AUD-RW-L01-U5-LS5-V02","script":"dessert. We have fruit for dessert."},{"id":"AUD-RW-L01-U5-LS5-V03","script":"fresh. This bread is fresh."},{"id":"AUD-RW-L01-U5-LS5-V04","script":"bowl. I eat soup from a bowl."},{"id":"AUD-RW-L01-U5-LS5-V05","script":"glass. A glass of water, please."},{"id":"AUD-RW-L01-U5-LS5-V06","script":"spoon. Use a spoon for the rice."},{"id":"AUD-RW-L01-U5-LS5-V07","script":"half. Fill half your plate with vegetables."},{"id":"AUD-RW-L01-U5-LS5-VID","script":"Welcome to Noura's Café! Today you make a healthy menu card. Plan: choose a main food, vegetables, fruit and a drink. Half the plate is vegetables and fruit! Draft: I eat rice and chicken. I eat a bowl of salad. For dessert, I eat dates. I drink a glass of milk. Revise: add why! It is healthy and it gives me energy. Edit: capitals in the title, a comma after For dessert, periods. Check! Publish: put your menu in our class café. Read it to a customer!"}]}],"unit_test":[{"q":"A long yellow fruit is a ___.","answer":"banana","explanation":"Bananas are long and yellow.","explanation_ar":"الموز طويل وأصفر.","options":["apple","date","banana","egg"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"We cook small white grains. They are ___.","answer":"rice","explanation":"Rice is small grains.","explanation_ar":"الأرز حبوب صغيرة.","options":["milk","juice","rice","cheese"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"A hen gives us this food with a shell.","answer":"an egg","explanation":"Eggs have shells.","explanation_ar":"البيضة لها قشرة.","options":["a banana","a salad","a spoon","an egg"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Mona did not eat lunch. Now she is ___.","answer":"hungry","explanation":"No lunch = hungry.","explanation_ar":"جائعة.","options":["fresh","hungry","sweet","healthy"],"dok":1,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"You eat soup with a ___.","answer":"spoon","explanation":"Soup is eaten with a spoon.","explanation_ar":"نأكل الحساء بملعقة.","options":["glass","menu","plate of milk","spoon"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Carrots and cucumbers are ___.","answer":"vegetables","explanation":"They are vegetables.","explanation_ar":"خضراوات.","options":["vegetables","drinks","desserts","meals"],"dok":1,"skill":"word groups","_part":"Part A – Words"},{"q":"The evening meal is ___.","answer":"dinner","explanation":"Evening = dinner.","explanation_ar":"العشاء.","options":["breakfast","dinner","lunch","a snack"],"dok":1,"skill":"word groups","_part":"Part A – Words"},{"q":"Fruit and vegetables are good for your body. They are ___.","answer":"healthy","explanation":"Good for the body = healthy.","explanation_ar":"صحية.","options":["healthy","hungry","slow","tiny"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which phrase about fruit is written correctly?","answer":"an apple and a banana","explanation":"Spaces and a/an.","explanation_ar":"مسافات وa/an.","options":["an appleand a banana","an apple and a banana","a apple and an banana","an apple and banana a"],"dok":1,"skill":"conventions","_part":"Part D – Check the sentences"},{"q":"Which word does NOT belong with the others?","answer":"chicken","explanation":"Chicken is a food; the others are drinks.","explanation_ar":"الدجاج طعام والبقية مشروبات.","options":["milk","water","chicken","juice"],"dok":1,"skill":"word groups","_part":"Part D – Check the sentences"},{"q":"Join: *I wash the apple. I eat it.*","answer":"I wash the apple and I eat it.","explanation":"Sentence + and + sentence.","explanation_ar":"جملة + and + جملة.","options":["I wash the apple and.","And I wash I eat the apple.","I wash the appleand I eat it.","I wash the apple and I eat it."],"dok":2,"skill":"joining sentences","_part":"Part D – Check the sentences"},{"q":"Which sentence gives an opinion?","answer":"I think salad is yummy.","explanation":"I think = opinion.","explanation_ar":"I think رأي.","options":["I think salad is yummy.","Salad has tomatoes.","Faris washes the vegetables.","Grandmother cuts them."],"dok":2,"skill":"opinion","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Write 4 sentences about a healthy breakfast. Use and in two sentences.","model":"My healthy breakfast is yummy. I eat eggs and bread. I drink a glass of milk. For dessert, I eat dates and it gives me energy.","marks":20}});
